    std::string s = str;
    while (true) {
        std::string t;
        for (char c : s) {
            t += c >= 'a' ? c - 32 : c + 32;
        }
        s += t;
        if (s.size() > 2 * n) {
            break;
        }
    }
    for (int i = 2 * n; i < s.size(); i++) {
        if (s[i] == s[i - n]) {
            cycle.push_back(i - n);
            break;
        }
    }
    int len = 0;
    if (cycle.empty()) {
        len = s.size();
    } else {
        len = cycle[0];
