#include <bits/stdc++.h>
using namespace std;

const int N = 500000 + 5;

int n;
int a[N];
int ac[N];

struct SegmentTree {
    int tree[N << 4];
    int lazy[N << 4];

    void update(int l, int r, int val, int node = 1, int start = 0, int end = n) {
        if (l > end || r < start) return;
        if (l <= start && r >= end) {
            tree[node] += val;
            lazy[node] += val;
            return;
        }
        int mid = (start + end) / 2;
        update(l, r, val, node << 1, start, mid);
        update(l, r, val, node << 1 | 1, mid + 1, end);
        tree[node] = tree[node << 1] + tree[node << 1 | 1];
    }

    int query(int pos, int node = 1, int start = 0, int end = n) {
        if (start == end) return tree[node];
        int mid = (start + end) / 2;
        if (lazy[node]) {
            tree[node << 1] += lazy[node] * (mid - start + 1);
            tree[node << 1 | 1] += lazy[node] * (end - mid);
