#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

int main() {
    int n = 5;
    std::vector<int> scores(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> scores[i];
    }

    // Generate all possible participant names and scores
    std::vector<std::pair<int, std::string>> participants;
    for (int mask = 1; mask <= 31; ++mask) {
        int score = 0;
        std::string name;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                score += scores[i];
                name += 'A' + i;
            }
        }
        participants.emplace_back(-score, name);
    }

    // Sort participants by score in descending order and then by name
    std::sort(participants.begin(), participants.end());

    // Print participant names
    for (const auto& participant : participants) {
        std::cout << participant.second << std::endl;
    }

    return 0;
}
