const int N = 2e5 + 10;
const ll LINF = 1e18;
const int INF = 1e9;
const ld PI = 4*atan((ld)1);
const int dx[4] = {1,0,-1,0}, dy[4] = {0,1,0,-1};

class UnionFind {
public:
    vector<int> parent, rank;
    int cnt;

    UnionFind(int n) : cnt(n), parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        parent[y] = x;
        if (rank[x] == rank[y]) ++rank[x];
        --cnt;
        return true;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return parent.count(find(x));
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    UnionFind uf(n);
    vector<pii> e;
    for (int i = 0; i < m; ++i) {
        int v, u;
        cin >> v >> u;
        if (v > u) swap(v, u);
        e.push_back({v, u});
    }
    int res = 0;
    for (auto& edge : e) {
        if (!uf.unite(edge.fi - 1, edge.se - 1)) ++res;
    }
    cout << res << '\n';
}
