using namespace std;

int main() {
  long long x;
  cin >> x;

  // Use Stirling's approximation to estimate N
  double estN = (x > 0) ? (sqrt(2 * M_PI * x) + x * (log(x) - 1)) / M_E : 0;
  int N = static_cast<int>(round(estN));

  // Refine the estimate
  while (true) {
    long long factorial = 1;
    for (int i = 1; i <= N; ++i) {
      factorial *= i;
      if (factorial == x) {
        cout << N << endl;
        return 0;
      }
      if (factorial > x) {
        --N;
        break;
      }
    }
    if (factorial < x) {
      ++N;
    }
  }

  return 0;
}

