    cin >> N >> X >> K;

    vector<vector<Data>> g(N+1);
    for (int i = 0; i < N; i++) {
        ll p, u, c;
        cin >> p >> u >> c;
        c--;
        g[c].emplace_back(p, u);
    }

    const ll INF = -2e18;
    vector<ll> dp(X + 1,INF);
    dp[0] = 0;
    for (auto& gc : g) {
        sort(gc.begin(), gc.end());
        vector<ll> prefix_sum(gc.size() + 1, 0);
        for (int i = 0; i < gc.size(); i++) {
            prefix_sum[i+1] = prefix_sum[i] + gc[i].second;
        }
        for (int i = 0; i < gc.size(); i++) {
            auto [p, u] = gc[i];
            for (int x = X; x >= p; x--) {
                if (dp[x - p] != INF) {
                    dp[x] = max(dp[x], dp[x-p] + u);
                }
            }
            for (int j = i; j >= 0; j--) {
                auto [pp, uu] = gc[j];
                if (pp > X) break;
                if (dp[X - pp] != INF) {
                    dp[X] = max(dp[X], dp[X - pp] + prefix_sum[i+1] - prefix_sum[j] + K);
                }
            }
        }
    }

    ll ans = 0;
    for (int x = 0; x <= X; x++) {
        ans = max(ans, dp[x]);
    }
    cout << ans << endl;
    return 0;
}
