using ll = long long;
using i32 = int;
using i64 = long long;
using i128 = __int128;

template <typename T>
ostream& operator<<(ostream& o, const vector<T>& vec) {
  o << '[';
  for (int i = 0; i < vec.size(); ++i) {
    o << vec[i];
    if (i != vec.size() - 1) o << ',';
  }
  return o << ']';
}

constexpr int M = 2e5 + 5, mod = 1e9 + 7; // 998244353
constexpr double pi = acos(-1), eps = 1e-9;

void solve() {
  int n;
  cin >> n;
  vector<int> a(n);
  for (auto& i : a) cin >> i;
  int ans = 0;
  for (int s = 0; s <= 1; ++s) {
    vector<bool> vis(n + 1);
    int cnt = 0;
    for (int i = s; i + 1 < n; i += 2) {
      if (a[i] == a[i + 1] && !vis[a[i]]) {
        cnt += 2;
        vis[a[i]] = 1;
      } else {
        while (cnt) {
          if (a[i] == a[i + 1] && a[i - cnt] == a[i]) break;
          vis[a[i - cnt]] = 0;
          cnt -= 2;
        }
      }
      ans = max(ans, cnt);
    }
  }
  cout << ans << endl;
  return;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int t{1};
  // cin >> t;
  while (t--) {
    solve();
  }

  return 0;
}
