    for (int i = 0; i < n; i++)
    {
        cin >> P[i];
    }

    auto check = [&](long long mid) -> pair<i128, i128>
    {
        i128 cost = 0, cnt = 0;
        for (int i = 0; i < n; i++)
        {
            if (mid < P[i])
            {
                continue;
            }

            long long upper = mid / P[i];
            long long k = (upper + 1) / 2;

            cnt += k;
            cost += i128(P[i]) * k * k;

            if (cost > m)
            {
                break;
            }
        }

        return {cost, cnt};
    };

    long long l = 0, r = m + 1;
    while (r - l > 1)
    {
        long long mid = l + (r - l) / 2;
        if(check(mid).first <= m) l = mid; else r = mid;
    }
    {
        auto [cost, cnt] = check(l);
        long long ans = cnt;
        long long left = m - cost;
        for (int i = 0; i < n; i++)
        {
            if (l < P[i]) continue;
            long long add = min(left / P[i], (long long)1e18);
            long long tmpCnt = 0;
            long long tmpCost = 0;
            long long upper = l / P[i];
            long long k = (upper + 1) / 2;
            tmpCnt += k;
            tmpCost += i128(P[i]) * k * k;
            long long remain = left - (tmpCost - cost);
            long long delta = min(add, remain / (2 * l / P[i] + 1));
            ans += delta;
            if (ans >= cnt + left / l) break;
