#include <bits/stdc++.h>

using namespace std;
using i128 = __int128_t;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    vector<pair<long long, long long>> P(n);
    for (int i = 0; i < n; i++)
    {
        cin >> P[i].second;
        P[i].first = i;
    }
    sort(P.begin(), P.end(), [](const auto& a, const auto& b) {
        return a.second < b.second;
    });

    auto check = [&](long long mid) -> pair<i128, i128>
    {
        i128 cost = 0, cnt = 0;
        for (int i = 0; i < n; i++)
        {
            long long upper = mid / P[i].second;
            long long k = upper;

            cnt += k;
            cost += i128(P[i].second) * k * k;

            if (cost > m)
            {
                break;
            }
        }

        return {cost, cnt};
    };

    long long l = 0, r = m + 1;
    while (r - l > 1)
    {
        long long mid = l + (r - l) / 2;
        (check(mid).first <= m ? l : r) = mid;
    }
    {
        auto [cost, cnt] = check(l);
        long long ans = cnt + (m - cost) / l;
        cout << fixed << setprecision(15);
        cout << ans << endl;
    }

    return 0;
}
