    vector<int> sA;
    vector<int> sB;

    DisjointSet(int n) : par(n + 1), sA(n + 1), sB(n + 1) {
        for (int i = 1; i <= n; i++) {
            par[i] = i;
        }
    }

    int get(int v) {
        if (par[v] == v) return v;
        return par[v] = get(par[v]);
    }

