        v = get(v);
        if (u == v) return;
        int x = min(sA[u], sB[v]);
        int y = min(sA[v], sB[u]);
        ans += (ll)(x + y) * w;
        par[u] = v;
        sA[v] += sA[u] - (x + y);
        sB[v] += sB[u] - (x + y);
    }
};

