typedef long long LL;

const int N = 1000010;

int n, q;
int fenwick[N];
int pos[N];

void update(int idx, int val) {
    while (idx <= n) {
        fenwick[idx] += val;
        idx += idx & -idx;
    }
}

int query(int idx) {
    int sum = 0;
    while (idx > 0) {
        sum += fenwick[idx];
        idx -= idx & -idx;
    }
    return sum;
}

void solve() {
    cin >> n >> q;
