using namespace std;

typedef long long LL;
typedef pair<int, int> PII;

const int N = 100010;

struct SegmentTree {
    vector<int> tree;
    int n;

    SegmentTree(int n) : n(n), tree(4 * n, 0) {}

    void update(int p, int val) {
        update(1, 0, n - 1, p, val);
    }

    void update(int node, int start, int end, int p, int val) {
        if (start == end) {
            tree[node] = val;
            return;
        }
        int mid = (start + end) / 2;
        if (p <= mid) update(2 * node, start, mid, p, val);
        else update(2 * node + 1, mid + 1, end, p, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    int query(int l, int r) {
        return query(1, 0, n - 1, l, r);
    }

    int query(int node, int start, int end, int l, int r) {
        if (l > end || r < start) return 0;
        if (l <= start && end <= r) return tree[node];
        int mid = (start + end) / 2;
        return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r);
    }
};

void solve() {
    int n, q;
    cin >> n >> q;

    vector<int> siz(n + 1), idx(n + 1);
    for (int i = 1; i <= n; i++) siz[i] = 1, idx[i] = i;

    SegmentTree st(n);
    for (int i = 1; i <= n; i++) {
        if (i != 1) st.update(i - 1, 0);
        st.update(i - 1, 1);
    }

    int cnt = 0;
    for (int _ = 1; _ <= q; _++) {
        int op, x, h;
        cin >> op;

        if (op == 1) {
            cin >> x >> h;

            if (siz[idx[x]] == 2) cnt--;
            siz[idx[x]]--;
            st.update(idx[x] - 1, max(0, siz[idx[x]] - 1));

            if (siz[h] == 1) cnt++;
            idx[x] = h, siz[h]++;
            st.update(h - 1, max(0, siz[h] - 1));
        } else {
            cout << st.query(0, n - 1) << '\n';
        }
    }
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);

    int T = 1;
    // cin >> T;

    while (T--) {
        solve();
    }

    return 0;
}
