#include <bits/stdc++.h>

using namespace std;

typedef long long LL;

const int N = 1000010;

int n, q;
int p[N], cnt[N], bit[N];

void add(int x, int v) {
    for (; x <= n; x += x & -x) bit[x] += v;
}

int sum(int x) {
    int r = 0;
    for (; x; x -= x & -x) r += bit[x];
    return r;
}

void solve() {
    cin >> n >> q;
    for (int i = 1; i <= n; i++) p[i] = i, cnt[i] = 1, bit[i] = 0;
    for (int i = 1; i <= n; i++) add(cnt[i], 1);

