```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <string>

using namespace std;

int n, m;
vector<string> grid;
string target = "YOKOHAMA";
int target_len = 8;
int directions[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

bool isValid(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < m;
}

int countYokohamaTraces() {
    int count = 0;
    queue<pair<pair<int, int>, int>> q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'Y') {
                q.push({{i, j}, 0});
            }
        }
    }

    while (!q.empty()) {
        auto [pos, index] = q.front(); q.pop();
        if (index == target_len - 1) {
            count++;
            continue;
        }

        for (int i = 0; i < 4; ++i) {
            int nx = pos.first + directions[i][0];
            int ny = pos.second + directions[i][1];
            if (isValid(nx, ny) && grid[nx][ny] == target[index + 1]) {
                q.push({{nx, ny}, index + 1});
            }
        }
    }
    return count;
}

int main() {
    cin >> n >> m;
    grid.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    int result = countYokohamaTraces();
    cout << result << endl;

    return 0;
}
