#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 200000;
static const int LOG  = 18;

int N, Q;
long long A[MAXN+5];
int p[MAXN+5], d[MAXN+5];
int st[LOG+1][MAXN+5];
int lg2[MAXN+5];

inline int rmq(int l, int r) {
    if (l > r) return 0;
    int len = r - l + 1;
    int k = lg2[len];
    return max(st[k][l], st[k][r - (1<<k) + 1]);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    cin >> Q;
    vector<pair<int,int>> qs(Q);
    for (int i = 0; i < Q; i++) {
        cin >> qs[i].first >> qs[i].second;
        qs[i].first--;
        qs[i].second--;
    }

    int j = 0;
    for (int i = 0; i < N; i++) {
        j = max(j, i+1);
