        p[i] = (j < N ? j : N);
    }

    for (int i = 0; i < N; i++) {
        if (p[i] == N) d[i] = N+1; else d[i] = p[i] - i;
    }

    lg2[1] = 0;
    for (int i = 2; i <= N; i++) lg2[i] = lg2[i>>1] + 1;

    for (int i = 0; i < N; i++) st[0][i] = d[i];
    for (int k = 1; k <= LOG; k++) {
        int len = 1 << k;
        for (int i = 0; i + len - 1 < N; i++) {
            st[k][i] = max(st[k-1][i], st[k-1][i + (1<<(k-1))]);
        }
    }

    for (auto &qr : qs) {
        int L = qr.first;
        int R = qr.second;
        int m = R - L + 1;

        int lo = (m + 1) / 2;
        int hi = m;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            int right = R - mid;
            if (rmq(L, right) <= mid) hi = mid; else lo = mid + 1;
        }
        int D = lo;
        int K = m - D;
        cout << K << "\n";
    }

    return 0;
}
