    //    p[i] = smallest j>i with A[j] >= 2*A[i], or N if none
    int j = 0;
    for (int i = 0; i < N; i++) {
        j = max(j, i+1);
        while (j < N && A[j] < 2LL * A[i]) 
            j++;
        p[i] = (j < N ? j : N);
    }

    // 3) build the d-array
    //    d[i] = p[i] - i  (>=1), or large if p[i]=N
