    for (int i = 0; i < N; i++)
        st[0][i] = d[i];
    for (int k = 1; k <= LOG; k++) {
        int len = 1 << k;
        for (int i = 0; i + len - 1 < N; i++) {
            st[k][i] = max(st[k-1][i], st[k-1][i + (1<<(k-1))]);
        }
    }

    // 6) answer queries
    //    For each [L,R], let m = R-L+1.
    //    Binary‐search minimal D in [ceil(m/2)..m] with
    //       max_{i=L..R-D} d[i] <= D
    //    Then K = m - D.
    for (auto &qr : qs) {
        int L = qr.first - 1;
        int R = qr.second - 1;
        int m = R - L + 1;

        int lo = (m + 1) / 2;  // ceil(m/2)
        int hi = m;
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            int right = R - mid;
            // check if sub‐range [L..right] is safe
            if (rmq(L, right) <= mid) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        int D = lo;
        int K = m - D;
        cout << K << "\n";
    }

    return 0;
}
