using namespace std;

void bfs(vector<vector<int>>& dist, vector<vector<char>>& grid, int x, int y, int d) {
    int h = grid.size();
    int w = grid[0].size();
    queue<pair<int, int>> q;
    q.push({x, y});
    dist[x][y] = 0;
    while (!q.empty()) {
        int cx = q.front().fi;
        int cy = q.front().se;
        q.pop();
        for (int dx = -d; dx <= d; dx++) {
            for (int dy = -d; dy <= d; dy++) {
                int nx = cx + dx;
                int ny = cy + dy;
                if (nx < 0 || nx >= h || ny < 0 || ny >= w || grid[nx][ny] == '#' || dist[nx][ny] != -1) continue;
                if (abs(dx) + abs(dy) > d) continue;
                dist[nx][ny] = dist[cx][cy] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void solve(){
    int h, w, d;
    cin >> h >> w >> d;
    vector<vector<char>> grid(h, vector<char>(w));
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++) cin >> grid[i][j];
    }
    int ans = 0;
    vector<vector<int>> dist(h, vector<int>(w, -1));
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(grid[i][j] == '.') {
                bfs(dist, grid, i, j, d);
                break;
            }
        }
    }
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(grid[i][j] == '.') ans += (dist[i][j] != -1);
        }
    }
    cout << ans << endl;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int _ = 1;
