class UnionFind {
public:
    vector<int> parent;
    vector<int> rank;
    vector<unordered_set<int>> nei;

    UnionFind(int n) : parent(n), rank(n, 0), nei(n) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }

    int findp(int x) {
        return parent[x] == x ? x : parent[x] = findp(parent[x]);
    }

    void unite(int x, int y) {
        x = findp(x);
        y = findp(y);
        if (x == y) return;
        if (rank[x] < rank[y]) swap(x, y);
        parent[y] = x;
        if (rank[x] == rank[y]) rank[x++;
        merge_nei(x, y);
    }

    void merge_nei(int r, int s) {
        if (nei[s].empty()) return;
        for (int v : nei[s]) {
            nei[r].insert(v);
            nei[v].erase(s);
            nei[v].insert(r);
        }
        nei[s].clear();
    }

    bool connected(int x, int y) {
        return findp(x) == findp(y);
    }

    bool has_path(int x, int y) {
        return nei[findp(x)].count(findp(y));
    }
};

