#include <bits/stdc++.h>
using namespace std;
using ll = long long;
constexpr int M = 10000;
constexpr ll P = 1000000007;

int main() {
  ll n, s, c;
  cin >> n >> s >> c;
  vector<array<ll, 3>> alr(n);
  for (auto &[a, l, r] : alr) cin >> a >> l >> r;

  // ベクトル (P-k, k) との内積を最小化する多角形上の点の計算 (0 <= k <= P)
  auto get_vertex = [&](ll k) {
