#include <algorithm>
#include <unordered_map>

using namespace std;

struct Person {
    int label;
    int value;
};

bool comparePeople(const Person& a, const Person& b) {
    return a.value < b.value;
}

int main() {
    int n;
    cin >> n;

    vector<Person> people(n);
    unordered_map<int, int> counter;

    for (int i = 0; i < n; i++) {
        cin >> people[i].value;
        counter[people[i].value]++;
        people[i].label = i + 1;
    }

    sort(people.begin(), people.end(), comparePeople);

    int ans = -1, mx = 0;
    for (auto& person : people) {
        if (counter[person.value] == 1 && person.value > mx) {
            ans = person.label;
            mx = person.value;
        }
    }

    cout << ans << endl;
    return 0;
}
