ll safeMult(ll a, ll b) {
    if (a == 0 || b == 0) return 0;
    if (a > INF / b) return INF;
    return a * b;
}

ll Pow(ll base, ll exp) {
    ll result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = safeMult(result, base);
            if (result == INF) return INF;
        }
        base = safeMult(base, base);
        if (base == INF) return INF;
        exp /= 2;
    }
    return result;
}

bool isPerfectSquare(ll n) {
    ll root = sqrt(n);
    return root * root == n;
}

bool isPowerOfTwo(ll n) {
    return n > 0 && (n & (n - 1)) == 0;
}

ll setBitsUpToHighestBit(ll x) {
    x |= x >> 1;
    x |= x >> 2;
    x |= x >> 4;
    x |= x >> 8;
    x |= x >> 16;
    return x;
}

bool isPrime(ll n) {
    if (n < 2) return false;
    for (ll i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

vector<ll> generatePrimes(ll n) {
    vector<bool> isPrime(n + 1, true);
    vector<ll> primes;
    isPrime[0] = isPrime[1] = false;

    for (int p = 2; p <= n; ++p) {
        if (isPrime[p]) {
            primes.push_back(p);
            for (int multiple = 2 * p; multiple <= n; multiple += p) {
                isPrime[multiple] = false;
            }
        }
    }
    return primes;
}

ll xorRange(ll l, ll r) {
    // XOR from 0 to a given number x
    auto xorUpto = [](ll x) -> ll {
        ll rem = x % 4;
        if (rem == 0) {
            return x;
        }
        else if (rem == 1) {
            return 1;
        }
        else if (rem == 2) {
            return x + 1;
        }
        else {
            return 0;
        }
    };
    return xorUpto(r) ^ xorUpto(l - 1);
}


