using namespace std;

int main() {
  int n;
  cin >> n;

  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    a[i]--;
  }

  unordered_map<int, int> left_count, right_count;
  int distinct_count = 0;

  // Initialize right_count and distinct_count
  for (int num : a) {
    right_count[num]++;
    if (right_count[num] == 1) {
      distinct_count++;
    }
  }

  int max_sum = 0;
  for (int i = 0; i < n - 1; i++) {
    int left_num = a[i];
    int right_num = a[i + 1];

    // Update counts
    left_count[left_num]++;
    if (left_count[left_num] == 1) {
      distinct_count++;
    }
    right_count[left_num]--;
    if (right_count[left_num] == 0) {
      distinct_count--;
    }

    right_count[right_num]--;
    if (right_count[right_num] == 0) {
      distinct_count--;
    }
    left_count[right_num]++;
    if (left_count[right_num] == 1) {
      distinct_count++;
    }

    max_sum = max(max_sum, distinct_count);
  }

  cout << max_sum << endl;
  return 0;
}

