// AOJ #3614
// Camp room assignment 2025.2.1

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 998244353;

#define gc() getchar_unlocked()
#define pc(c) putchar_unlocked(c)

int Cin() {   // 非負整数の入力
    int n = 0; int c = gc();
    do n = 10 * n + (c & 0xf); while ((c = gc()) >= '0');
    return n;
}

void Cout(int n) { // 非負整数の表示（出力）
    char b[30];
    if (!n) pc('0');
    else {
        //      if (n < 0) pc('-'), n = -n;
        int i = 0; while (n) b[i++] = n % 10 + '0', n /= 10;
        while (i--) pc(b[i]);
    }
    pc('\n');
}

ll modexp(ll base, ll exp, ll mod=MOD) {
    ll res = 1;
    base %= mod;
    while(exp > 0) {
        if(exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

void precomputeFactorials(int n_max, vector<ll>& fact, vector<ll>& invfact) {
    fact.resize(n_max+1);
    invfact.resize(n_max+1);
    fact[0] = 1;
    for (int i = 1; i <= n_max; i++)
        fact[i] = fact[i-1] * i % MOD;
    invfact[n_max] = modexp(fact[n_max], MOD-2, MOD);
    for (int i = n_max; i > 0; i--)
        invfact[i-1] = invfact[i] * i % MOD;
}

ll binom(int n, int k, const vector<ll>& fact, const vector<ll>& invfact) {
    if(k < 0 || k > n) return 0;
    return fact[n] * ((invfact[k] * invfact[n-k]) % MOD) % MOD;
}

// Main function
int main(){
    int m = Cin();
    int M = 2 * m;
    vector<ll> fact, invfact;
    precomputeFactorials(M, fact, invfact);

    ll x = ((ll)m - 1) % MOD;
    if(x < 0) x += MOD;

    int maxPow = m + 1;
    vector<ll> powX(maxPow+1, 0);
    powX[0] = 1;
    for (int i = 1; i <= maxPow; i++)
        powX[i] = (powX[i-1] * x) % MOD;

    ll mm2 = ((ll)m * m) % MOD;
    vector<ll> powM2(m+1, 0);
    powM2[0] = 1;
    for (int i = 1; i <= m; i++)
        powM2[i] = (powM2[i-1] * mm2) % MOD;

    ll onePlusX = (1 + x) % MOD;
    ll c = (onePlusX * onePlusX) % MOD;

    vector<ll> A(m+1, 0);
    A[1] = 1;
    for (int n = 1; n < m; n++){
        ll term1 = binom(2*n, n, fact, invfact);
        ll term2 = binom(2*n, n-1, fact, invfact);
        ll add1 = (term1 * powX[n]) % MOD;
        ll add2 = (term2 * powX[n+1]) % MOD;
        ll nextA = ( c * A[n] ) % MOD;
        nextA = ( nextA + add1 ) % MOD;
        nextA = ( nextA + MOD - add2 ) % MOD;
        A[n+1] = nextA;
    }
    for (int n = 1; n <= m; n++){
        ll ans = ( powM2[n] + MOD - ( (ll)m * A[n] ) % MOD ) % MOD;
        Cout(ans);
    }
    return 0;
}

