#include <iostream>
#include <vector>
#include <iomanip>
#include <algorithm>
#include <cmath>

using namespace std;

const int MOD = 998244353;
const int N = 8;
const int X = 5000;

vector<int> fact(X + 1), inv_fact(X + 1);

void precompute_factorials() {
    fact[0] = 1;
    for (int i = 1; i <= X; ++i) {
        fact[i] = (long long)fact[i-1] * i % MOD;
    }
    inv_fact[X] = pow(fact[X], MOD - 2, MOD);
    for (int i = X - 1; i >= 0; --i) {
        inv_fact[i] = (long long)inv_fact[i+1] * (i + 1) % MOD;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x;
    cin >> n >> x;

    vector<int> s(n), c(n), p(n);
    for (int i = 0; i < n; ++i) {
        cin >> s[i] >> c[i] >> p[i];
    }

    precompute_factorials();

    vector<vector<double>> dp(1 << n, vector<double>(x + 1, 0.0));

    for (int mask = (1 << n) - 1; mask >= 0; --mask) {
        for (int i = 0; i < n; ++i) {
            if (!(mask & (1 << i))) {
                for (int j = c[i]; j <= x; ++j) {
                    double success_prob = p[i] / 100.0;
                    double fail_prob = 1.0 - success_prob;
                    int new_mask = mask | (1 << i);
                    int remaining_x = j - c[i];
                    double success_value = s[i] + dp[new_mask][remaining_x];
                    double fail_value = dp[mask][remaining_x];
                    dp[mask][j] = max(dp[mask][j], success_prob * success_value + fail_prob * fail_value);
                }
            }
        }
    }

    cout << fixed << setprecision(15) << dp[0][x] << endl;

    return 0;
}
