// AOJ #3630 Half Plane Painting
// 2025.4.26

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

#define gc() getchar_unlocked()

int Cin() {
    int n = 0; int c = gc();
    if (c == '-') { c = gc();
        do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
        return -n;
    }
    do n = 10*n + (c & 0xf), c = gc(); while (c >= '0');
    return n;
}

const int MAXN = 4000;
struct P { ll x, y; };
bitset<MAXN> bitL[MAXN], bitR[MAXN];
int cntL[MAXN], cntR[MAXN];
bool used[MAXN], inq[MAXN];
int q[MAXN];

int main(){
    int N = Cin();
    vector<P> p(N);
    for(int i = 0; i < N; i++) p[i].x = Cin(), p[i].y = Cin();

    for(int k = 0; k < N; k++){
        auto &A = p[k];
        auto &B = p[(k+1)%N];
        for(int e = 0; e < N; e++){
            if(e == k) continue;
            auto &C = p[e];
            auto &D = p[(e+1)%N];
            ll c1 = (B.x - A.x) * (C.y - A.y) - (B.y - A.y) * (C.x - A.x);
            ll c2 = (B.x - A.x) * (D.y - A.y) - (B.y - A.y) * (D.x - A.x);
            if(c1 < 0 || c2 < 0) bitL[k].set(e);
            if(c1 > 0 || c2 > 0) bitR[k].set(e);
        }
        cntL[k] = bitL[k].count();
        cntR[k] = bitR[k].count();
    }

    int ql = 0, qr = 0, sel = 0;
    for(int i = 0; i < N; i++){
        if(cntL[i] == 0 || cntR[i] == 0){
            q[qr++] = i;
            inq[i] = true;
        }
    }

    while(ql < qr){
        int e = q[ql++];
        inq[e] = false;
        if(used[e]) continue;
        used[e] = true;
        sel++;
        for(int k = 0; k < N; k++){
            if(used[k]) continue;
            if(bitL[k].test(e)){
                bitL[k].reset(e);
                if(--cntL[k] == 0 && !inq[k]){
                    q[qr++] = k;
                    inq[k] = true;
                }
            }
            if(bitR[k].test(e)){
                bitR[k].reset(e);
                if(--cntR[k] == 0 && !inq[k]){
                    q[qr++] = k;
                    inq[k] = true;
                }
            }
        }
    }
    cout << (sel == N ? "Yes" : "No") << endl;
    return 0;
}

