#include <bits/stdc++.h>
#define endl '\n'
using namespace std;
const int MAXN = 2 * 10^5 + 5;

struct Node {
    int size, cnt;
    bool operator<(const Node& other) const {
        return size < other.size;
    }
};

vector<int> graph[MAXN];
priority_queue<Node, vector<Node>, greater<Node>> pq;

void dfs(int x, int fa, int& n, int& k) {
    int size = 1, cnt = 0;
    for (int i : graph[x]) {
        if (i == fa) continue;
        dfs(i, x, n, k);
        size += graph[i].size();
        cnt++;
    }
    if (size == k) {
        pq.push({size, cnt});
        size = 0;
    }
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int n, k;
    cin >> n >> k;
    for (int i = 1; i < n * k; i++) {
        int x, y;
        cin >> x >> y;
        graph[x].push_back(y);
        graph[y].push_back(x);
    }

    int cnt = 0;
    dfs(1, -1, n, k);

    while (!pq.empty()) {
        Node node = pq.top();
        pq.pop();
        if (node.cnt > 2) {
            cout << "No\n";
            return 0;
        }
        cnt++;
    }

    cout << (cnt == n ? "Yes" : "No") << endl;
    return 0;
}
