const int B = 18;

void fwt(std::vector<int64_t>& a) {
    int n = a.size();
    for (int o = 1; o < n; o <<= 1) {
        for (int i = 0; i < n; i += o << 1) {
            for (int j = 0; j < o; j++) {
                int64_t x = a[i + j], y = a[i + j + o];
                a[i + j] = x + y;
                a[i + j + o] = x - y;
            }
        }
    }
}

void ifwt(std::vector<int64_t>& a) {
    int n = a.size();
    for (int o = 1; o < n; o <<= 1) {
        for (int i = 0; i < n; i += o << 1) {
            for (int j = 0; j < o; j++) {
                int64_t x = a[i + j], y = a[i + j + o];
                a[i + j] = (x + y) >> 1;
                a[i + j + o] = (x - y) >> 1;
            }
        }
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr), std::cout.tie(nullptr);

    int n, m;
    std::cin >> n >> m;
