        for (char c : s) x = (x << 1) | (c & 1);
        cnt[x++]++;
    }

    for (int i = 0; i < (1 << m); i++) {
        f[i] = std::min(__builtin_popcount(i), m - __builtin_popcount(i));
    }

    fwt(f);
    fwt(cnt);
