Modified to use Convolution and NTT */

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MOD = 998244353;

int add(int a, int b){ a += b; if(a >= MOD) a -= MOD; return a; }
int mul(long long a, long long b){ return int(a * b % MOD); }

const int N = 1 << 14;
int rev[N], w[N];
void init(){ 
    for(int i = 1; i < N; i++) rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << 14);
    w[0] = 1;
    int base = mul(3, (MOD - 1) / 2);
    for(int i = 1; i < N; i *= 2){
        int tw = mul(base, base);
        for(int j = 0; j < i; j++){
            w[j * 2] = w[j];
            w[j * 2 + 1] = mul(w[j], tw);
        }
        base = tw;
    }
}

void ntt(vector<int> &a){
    int n = a.size();
    assert(n == N);
    for(int i = 0; i < n; i++) if(i < rev[i]) swap(a[i], a[rev[i]]);
    for(int i = 2; i <= n; i *= 2){
        int half = i / 2;
        for(int j = 0; j < n; j += i){
            for(int k = 0; k < half; k++){
                int u = a[j + k], v = mul(a[j + k + half], w[k * (n / i)]);
                a[j + k] = add(u, v);
                a[j + k + half] = add(u, MOD - v);
            }
        }
    }
}
void intt(vector<int> &a){
    int n = a.size();
    int invn = mul(MOD - 1, MOD - 2);
    for(int i = 2; i <= n; i *= 2){
        int half = i / 2;
        for(int j = 0; j < n; j += i){
            for(int k = 0; k < half; k++){
                int u = a[j + k], v = a[j + k + half];
                a[j + k] = add(u, v);
                a[j + k + half] = mul(u, MOD - v);
            }
        }
    }
    for(int i = 0; i < n; i++) a[i] = mul(a[i], invn);
}

vector<int> conv(vector<int> a, vector<int> b){
    int n = a.size();
    vector<int> res(n, 0);
    if(n < 64){
        for(int i = 0; i < n; i++){
            for(int j = 0; j <= i; j++){
                res[i] = add(res[i], mul(a[j], b[i - j]));
            }
        }
        return res;
    }
    a.resize(N); b.resize(N);
    ntt(a); ntt(b);
    for(int i = 0; i < N; i++) res[i] = mul(a[i], b[i]);
    intt(res);
    res.resize(n);
    return res;
}

