using namespace std;

int n, m;
int b[405];                           // 存储 10^k % M
int ans;                              // 最终答案
int d[25][25];                        // 输入的原始网格
int a[25][25];                        // 预计算的贡献
auto cmp = [](long long a, long long b) { return a > b; };  // lambda comparator
vector<long long> c[25][25];          // 存储路径贡献

// 预计算贡献
void precompute() {
    int N = 2 * n - 1;
    b[1] = 1;
    for (int i = 2; i <= N; i++) b[i] = (b[i - 1] * 10) % m;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++) {
            cin >> d[i][j];
            a[i][j] = ((d[i][j] % m) * (b[N - i - j + 2] % m)) % m;
        }
}

// DFS 函数：i 表示搜索方向（0 为从 (1,1) 开始，1 为从 (n,n) 开始）
void dfs(int i, int x, int y, int s) {
    if (x + y == n + 1) {
        c[x][y].push_back(s);
        return;
    }
    s = (s + a[x][y]) % m;
    if (i) {
        if (x > 1) dfs(i, x - 1, y, s);
        if (y > 1) dfs(i, x, y - 1, s);
    } else {
        if (x < n) dfs(i, x + 1, y, s);
        if (y < n) dfs(i, x, y + 1, s);
    }
}

signed main() {
    ios::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
    cin >> n >> m;
    precompute();
    dfs(0, 1, 1, 0);
    dfs(1, n, n, 0);
    for (int i = 1; i <= n; i++) {
        sort(c[i][i].begin(), c[i][i].end(), cmp);
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < c[i][i].size(); j++) {
            ans = max(ans, c[i][i][j]);
        }
    }
    cout << ans;
    return 0;
}
