  for (int& count : coinCounts) {
    std::cin >> count;
  }

  int numStores;
  std::cin >> numStores;

  for (int i = 0; i < numStores; ++i) {
    int cost;
    std::cin >> cost;

    std::vector<int> neededCoins(COIN_DENOMINATIONS.size(), 0);
    int remainingCost = cost;
    for (int j = COIN_DENOMINATIONS.size() - 1; j >= 0; --j) {
      neededCoins[j] = remainingCost / COIN_DENOMINATIONS[j];
      remainingCost %= COIN_DENOMINATIONS[j];
    }

    for (int j = 0; j < COIN_DENOMINATIONS.size(); ++j) {
      coinCounts[j] -= neededCoins[j];
      for (int k = 0; k < j; ++k) {
        if (coinCounts[k] > 0) {
          int transferableAmount = coinCounts[k] * COIN_DENOMINATIONS[k] / COIN_DENOMINATIONS[j];
          coinCounts[j] += transferableAmount;
          coinCounts[k] %= COIN_DENOMINATIONS[k] / COIN_DENOMINATIONS[j];
        }
      }
      if (coinCounts[j] < 0) {
        coN();
        return 0;
      }
    }
  }

  coY();
  return 0;
}
