using namespace std;

typedef long long LL;
constexpr int mod = 998244353;

int n, k, L;

LL fac[500001], invfac[500001];

LL pow_mod(LL a, LL b) {
    LL res = 1;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void precompute_factorials(int max_n) {
    fac[0] = 1;
    for (int i = 1; i <= max_n; ++i) {
        fac[i] = fac[i - 1] * (LL)i % mod;
    }
    invfac[max_n] = pow_mod(fac[max_n], mod - 2);
    for (int i = max_n - 1; i >= 0; --i) {
        invfac[i] = invfac[i + 1] * (LL)(i + 1) % mod;
    }
}

LL binomial_coefficient(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fac[n] * invfac[k] % mod * invfac[n - k] % mod;
}

int main() {
    scanf("%d%d%d", &n, &k, &L);
    precompute_factorials(n);
    LL res = 1;
    for (int i = 1; i <= n; ++i) {
        res = res * (LL)(L - min(i - 1, n - k)) % mod;
    }
    printf("%lld\\n", res);
