const ll MOD = 1e9 + 7;

ll fac[2 * 1e5 + 5], inv_fac[2 * 1e5 + 5];

void precompute_factorials() {
    fac[0] = 1;
    for (ll i = 1; i <= 2 * 1e5 + 4; i++) {
        fac[i] = (fac[i - 1] * i) % MOD;
    }
    inv_fac[2 * 1e5 + 4] = pow(fac[2 * 1e5 + 4], MOD - 2, MOD);
    for (ll i = 2 * 1e5 + 3; i >= 0; i--) {
        inv_fac[i] = (inv_fac[i + 1] * (i + 1)) % MOD;
    }
}

ll combination(ll n, ll k) {
    if (k < 0 || k > n) return 0;
    return (fac[n] * inv_fac[k] * inv_fac[n - k]) % MOD;
}

