namespace IO
{
    inline void read() {}
    template<typename _Tint, typename... _Args>
    inline void read(_Tint &n, _Args &...args)
    {
        char c, lst;
        lst = '0';
        while (!isdigit(c = getchar()))
            lst = c;
        n = (c ^ '0');
        while (isdigit(c = getchar()))
            n = (n << 3) + (n << 1) + (c ^ '0');
        if (lst == '-')
            n = -n;
        read(args...);
    }
    inline void write() {}
    template<typename _Tint, typename... _Args>
    inline void write(_Tint a, const _Args &...args)
    {
        char s[128];
        int ptr = 0;
        while (a)
        {
            s[++ptr] = '0' + a % 10;
            a /= 10;
        }
        for (int i = ptr; i; --i)
            putchar(s[i]);
        write(args...);
    }
}
