#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>

using namespace std;

bool can_make_identical(vector<int>& A, vector<int>& B, int K) {
    int N = A.size();
    int tot = 0;
    unordered_map<int, int> last_pos;
    for (int i = 0; i < N; i++) {
        if (A[i] != B[i]) {
            tot++;
            if (last_pos.find(B[i]) != last_pos.end() && i - last_pos[B[i]] <= K) {
                continue;
            }
            if (last_pos.find(A[i]) != last_pos.end() && i - last_pos[A[i]] <= K) {
                last_pos[B[i]] = last_pos[A[i]];
            } else {
                return false;
            }
        }
        last_pos[A[i]] = i;
        last_pos[B[i]] = i;
    }
    return true;
}

void solve() {
    int N, K;
    cin >> N >> K;
    vector<int> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    for (int i = 0; i < N; i++) cin >> B[i];
    if (can_make_identical(A, B, K)) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    int T;
    cin >> T;
    while (T--) solve();
    return 0;
}
