{
    ll n; cin >> n;
    string s; cin >> s;
    ll count = 1;
    ll prefix_sum = 0;
    unordered_map<ll, ll> seen;
    seen[0] = 1;

    for(ll i = 0; i < s.size(); i++)
    {
        prefix_sum += (s[i] == '1') ? 1 : -1;
        if(seen.find(prefix_sum) != seen.end())
        {
            count *= 2;
        }
        seen[prefix_sum]++;
    }
    cout << count << endl;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    ll t = 1;
    cin >> t;
    while(t--)
    {
        solve();
    }
    return 0;
}

