long long powerMod(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long countValidPairs(long long m, long long x) {
    int multipleCount = (m - 1) / x + 1;
    int remainder = m - (m - 1) / x * x;
    int sum = ((remainder * multipleCount) % MOD * multipleCount) % MOD + 
              ((x - remainder) * ((multipleCount - 1) % MOD) * (multipleCount - 1) % MOD);
    return sum % MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    cin >> t;
    while (t--) {
        long long n, m;
        cin >> n >> m;

        long long palindromeArrays = (n & 1) ? powerMod(m, (n + 1) / 2) : powerMod(m, n / 2);
        long long totalCount = 0;

        for (int x = 1; x <= m; x++) {
            long long pairCount = countValidPairs(m, x);

            if (n & 1) 
                totalCount = (totalCount + (powerMod(pairCount, n / 2) * m) % MOD) % MOD;
            else 
                totalCount = (totalCount + powerMod(pairCount, n / 2)) % MOD;

            totalCount = (totalCount - palindromeArrays + MOD) % MOD;
        }

        totalCount = (totalCount - palindromeArrays + MOD) % MOD;
        cout << totalCount << "\n";
    }

    return 0;
}
