int solve() {
  int N, X;
  cin >> N >> X;
  // प्रत्येक संख्या के सभी स्थान (इंडेक्स) को स्टोर करने के लिए मैप
  unordered_map<int, vector<int>> occ;
  for (int x, i = 0; i < N; ++i) {
    cin >> x;
    occ[x].push_back(i); // संख्या x के इंडेक्स को स्टोर करें
  }

  int ans = 1; // न्यूनतम आवृत्ति 1 है (कम से कम एक तो होगा)

  // प्रत्येक संख्या (target) के लिए प्रोसेस करें
  for (auto &[target, idxs] : occ) {
    int m = idxs.size(); // target की मूल आवृत्ति
    ans = max(ans, m);   // मूल आवृत्ति को अपडेट करें

    // X=1 होने पर कुछ नहीं करना (गुणा करने से कोई बदलाव नहीं)
    if (X == 1) continue;

    // यदि target, X से विभाज्य नहीं है, तो skip करें
    if (target % X != 0) continue;

    // k = target / X (जिसे X से गुणा करने पर target मिलेगा)
    int k = target / X;
    auto it = occ.find(k);
    vector<int> k_idxs;

    // यदि k मौजूद है, तो उसके इंडेक्स लें
    if (it != occ.end()) {
      k_idxs = it->second;
    }

    int p = k_idxs.size(); // k की मूल आवृत्ति
    int min_psum = 0;      // न्यूनतम प्रीफिक्स योग
    int cur_psum = 0;      // वर्तमान प्रीफिक्स योग
    int i = 0, j = 0;      // दो पॉइंटर्स (k और target के इंडेक्स के लिए)

    // दो पॉइंटर्स का उपयोग करके सबसे अच्छा सबअरे खोजें
    while (i < m || j < p) {
      // दोनों सूचियों से अगला इंडेक्स चुनें
      int a = (i < m) ? idxs[i] : INT_MAX;
      int b = (j < p) ? k_idxs[j] : INT_MAX;

      bool advance_i = a < b; // किस सूची को आगे बढ़ाना है?
      int value = advance_i ? -1 : 1; // प्रीफिक्स योग में परिवर्तन

      cur_psum += value;
      // उपलब्ध अधिकतम आवृत्ति की गणना (current - min_prefix + m)
      ans = max(ans, cur_psum - min_psum + m);
      min_psum = min(min_psum, cur_psum);

      // चुनी गई सूची को आगे बढ़ाएँ
      if (advance_i) ++i;
      else ++j;
    }
  }
  return ans;
}

