int minOperations(string s) {
    int n = s.length();
    int ones = 0, zeros = 0;
    bool isAlternating = true;
    for (int i = 0; i < n; i++) {
        if (s[i] == '1') ones++;
        else zeros++;
        if (i > 0 && s[i] == s[i-1]) isAlternating = false;
    }
    if (isAlternating) return 0;
    int diff = abs(ones - zeros);
    return (diff <= 1) ? 1 : (diff <= 3) ? 2 : 3;
