void solve() {
    int n, k;
    std::cin >> n >> k;

    if (k == 1) {
        std::cout << -1 << std::endl;
        return;
    }

    // K >= 2 from here
    if (k == 2 && n % 2 == 1) { // N is odd
        std::cout << -1 << std::endl;
        return;
    }

    // General case: K >= 2.
    // And if K=2, then N must be even (otherwise caught above).

    std::vector<int> p(n);
    if (n % k == 1) {
        // This case implies K >= 3.
        // If K=2, then N must be even for this path. N%K = N%2 = 0.
        // So if N%K == 1, K cannot be 2. Thus K >= 3.
        // Use P_cyclic_3 (values start from 3, then wrap around to 1, 2).
        // P_idx = (idx + 2) % n + 1 (for 0-indexed idx)
        for (int i = 0; i < n; ++i) {
            p[i] = (i + 2) % n + 1;
        }
    } else {
        // N % K != 1. This includes N%K=0 and N%K=r where 1 < r < K.
        // (If K=2, N is even, so N%K = N%2 = 0, which is != 1).
        // Use P_cyclic_2 (values start from 2, then wrap around to 1).
        // P_idx = (idx + 1) % n + 1 (for 0-indexed idx)
        for (int i = 0; i < n; ++i) {
            p[i] = (i + 1) % n + 1;
        }
    }

    for (int i = 0; i < n; ++i) {
        std::cout << p[i] << (i == n - 1 ? "" : " ");
    }
    std::cout << std::endl;
}

