bool is_smoothly_increasing(vector<int> cs) {
    if (cs.size() == 1) return true;
    for (int i = 1; i < cs.size(); i++) {
        if (cs[i] <= cs[i - 1]) return false;
    }
    vector<int> diff;
    for (int i = 1; i < cs.size(); i++) {
        diff.push_back(cs[i] - cs[i - 1]);
    }
    return is_smoothly_increasing(diff);
}

