    while (t--) {
        int n;
        cin >> n;
        vector<int> cs(n), ans(n, '1');
        for (auto& a : cs) cin >> a;

        auto check = [&](int i) {
            vector<int> a = cs;
            a.erase(a.begin() + i);
            return is_smoothly_increasing(a);
        };

        for (int i = 0; i < n; i++) {
            if (!check(i)) ans[i] = '0';
        }
        string s(ans.begin(), ans.end());
        cout << s << endl;
    }
    return 0;
}
