#include <iostream>
#include <string>
#include <unordered_map>

const std::string str[] ={"la","le","lon","sha","she","shon","ta","te","ton"};
const std::unordered_map<std::string, int> trans_map = {
    {"la", 0}, {"le", 1}, {"lon", 2}, {"sha", 3}, {"she", 4}, {"shon", 5}, {"ta", 6}, {"te", 7}, {"ton", 8}
};

int trans(const std::string& s){
    int ans = 0;
    for (size_t i = 0; i < s.size(); ) {
        for (const auto& pair : trans_map) {
            if (i + pair.first.size() > s.size()) continue;
            bool flag = true;
            for (size_t k = 0; k < pair.first.size(); k++)
                if (s[i + k] != pair.first[k]) {
                    flag = false;
                    break;
                }
            if (flag) {
                ans = ans * 9 + pair.second;
                i += pair.first.size();
                break;
            }
        }
    }
    return ans;
}

void print(int a){
    if (a < 9) {
        std::cout << str[a];
        return;
    }
    print(a / 9);
    std::cout << str[a % 9];
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string s, t;
    std::cin >> s >> t;
    int a = trans(s), b = trans(t);
    print(a + b);
    std::cout << 's' << std::endl;
    return 0;
}
