#include <unordered_map>

const std::string str[] ={"la","le","lon","sha","she","shon","ta","te","ton"};
const int base = 9;

std::unordered_map<std::string, int> mapping;

int trans(const std::string& s){
    int ans = 0;
    for (int i = s.size() - 1; i >= 0; --i) {
        ans = ans * base + mapping[s.substr(i, 1)];
    }
    return ans;
}

void print(int a){
    if (a < base) {
        std::cout << str[a];
        return;
    }
    print(a / base);
    std::cout << str[a % base];
}

int main(){
    for (int i = 0; i < 9; ++i) {
        mapping[str[i]] = i;
    }
    std::string s, t;
    std::cin >> s >> t;
    int a = trans(s), b = trans(t);
    print(a + b);
    std::cout << 's' << std::endl;
    return 0;
}
