                int sum = 0;
                for(int i = 0; i < 3; i++){
                    if(dev & (1 << i))
                        sum += (n - dspp[i]);
                }
                minn = min(minn, sum);
            }
        }

        cout << minn << "\n";
    }

    return 0;
