void build(int m) {
    if (!ords[m].empty()) {
        return;
    } else {
        //vector<int> X(m);
        //dfs(0, m, 1, X);
    }

    auto encode = [&](const vector<int>& W) {
        int M = 1 << m;
        vector<int> sc(M, 0);
        for (int i = 0; i < M; ++i) {
            for (int j = 0; j < m; ++j) {
                if (i >> j & 1) {
                    sc[i] += W[j];
                }
            }
        }
        vector<int> ord(M, 0);
        iota(ord.begin(), ord.end(), 0);
        auto cmp = [&](int l, int r) {
            if (sc[l] == sc[r]) {
                return l < r;
            }
            return sc[l] < sc[r];
        };
        sort(ord.begin(), ord.end(), cmp);
        vector<int> ranks(M, 0);
        for (int i = 0, rk = -1; i < M; ++i) {
            if (i - 1 < 0 || sc[ord[i - 1]] != sc[ord[i]]) {
                ++rk;
            }
            ranks[ord[i]] = rk;
        }

        return ranks;
    };

    auto& scores = SC[m];
    int sz = 0;
    int osz = (int) scores.size();
    print(osz);
    set<vector<int>> S;
    int mx = 0;
    for (int i = 0; i < osz; ++i) {
        auto key = encode(scores[i]);
        if (S.count(key) == 0) {
            S.insert(key);
            scores[sz] = scores[i];
            mx = max(mx, accumulate(scores[i].begin(), scores[i].end(), 0));
            ords[m].push_back(key);
            ++sz;
        }
    }
    print(mx, sz);
    scores.resize(sz);
}

long long solve(vector<vector<int>>& A, vector<int>& R) {
    int n = (int) A.size();
    int m = (int) A[0].size();

    build(m);

    vector<int> ord(n, 0);
    for (int i = 0; i < n; ++i) {
        ord[R[i]] = i;
    }
    vector<int> F(n, 0);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (A[i][j]) {
                F[i] |= 1 << j;
            }
        }
    }

    long long res = 1LL << 62;
    vector<int> sc(n, 0);

    int M = 1 << m;

    vector<int> ranks(M, 0);
    vector<int> begs(M, 0);
    vector<int> cnts(M, 0);
    vector<int> ord2(n);
    vector<int> que(M, 0);
    auto calc = [&](const vector<int>& W) {
        long long res = 0;
        long long f = 0;
        for (int i = 0; i < n; ++i) {
            int r = W[F[i]];
            f |= 1LL << r;
            cnts[r] += 1;
        }
        int mx = __builtin_popcountll(f);
        for (int i = 0, cnt = 0; i < mx; ++i) {
            auto lsb = f & -f;
            f ^= lsb;
            int x = 63 - __builtin_clzll(lsb);
            ranks[x] = i;
            begs[x] = cnt;
            cnt += cnts[x];
            que[i] = x;
        }
        // print(F, mx, vector<int>(que.begin(), que.begin() + mx));
        for (auto idx : ord) {
            int f = W[F[idx]];
            // print(idx, n, f, begs[f], ranks[W[F[idx]]]);
            ord2[begs[f]++] = idx;
        }

        for (int i = mx - 1, sum = 0; i >= 0; --i) {
            auto x = que[i];
            int sz = cnts[x];
            assert(sz > 0);
            int l = sum;
            int r = sum + sz - 1;
            long long sfx = 0;
            long long s2 = 0;
            for (int j = sz - 1, k = n - sum - 1; j >= 0; --j, --k) {
                s2 += sfx;
                sfx += R[ord2[k]];
            }
            res += sfx * l + s2;
            sum += sz;
            cnts[x] = 0;
        }

        res *= -2;
        res += (n - 1) * 1LL * (n - 1 + 1) * (2LL * (n - 1) + 1) / 3;

        return res;
    };

    for (int i = 0; i < (int) ords[m].size(); ++i) {
        auto ans = calc(ords[m][i]);
        res = min(res, ans);
    }
    return res;
}


