int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while(t--){
        int n;
        cin >> n;
        // Using 1-indexing for contests.
        vector<long long> A(n+1), B(n+1);
        for (int i = 1; i <= n; i++){
            cin >> A[i];
        }
        for (int i = 1; i <= n; i++){
            cin >> B[i];
        }

        // dp[i] = minimum rating required at the start of contest i.
        // Base case: after contest n, we need rating >= 0.
        vector<long long> dp(n+2, 0);
        dp[n+1] = 0;

        // Process contests backwards.
        for (int i = n; i >= 1; i--){
            // Option 1: Eligible branch (if current rating R <= A[i])
            // We want: R + B[i] - 1 >= dp[i+1]  =>  R >= dp[i+1] - B[i] + 1.
            // Since rating cannot be negative, we take:
            long long cand1 = max(0LL, dp[i+1] - B[i] + 1);
            // This branch is valid only if cand1 <= A[i]
            bool eligibleValid = (cand1 <= A[i]);

            // Option 2: Not eligible branch (R > A[i], so no bonus, and rating becomes R - 1)
            // We need: R - 1 >= dp[i+1]  =>  R >= dp[i+1] + 1.
            // And also R > A[i] which is ensured by taking at least A[i]+1.
            long long cand2 = max(dp[i+1] + 1, A[i] + 1LL);

            if(eligibleValid)
                dp[i] = min(cand1, cand2);
            else
                dp[i] = cand2;
        }

        cout << dp[1] << "\n";
    }
    return 0;
}

