class Solution {
  public:
    int maximumSetSize(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        unordered_map<int, int> cnt1, cnt2;
        for (int i : nums1) cnt1[i]++;
        for (int i : nums2) cnt2[i]++;
        int intersection = 0;
        for (auto& p : cnt1) {
            if (cnt2.count(p.first)) intersection++;
        }
        int common = 0;
        for (auto& p : cnt1) {
            if (cnt2.count(p.first)) common = max(common, min(p.second, cnt2[p.first]));
        }
        return n - (n / 2 - common) + intersection;
    }
}

