// Comparison function for qsort
int cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main() {
    int T;
    scanf("%d", &T);

    while (T--) {
        int N;
        long long X;
        scanf("%d %lld", &N, &X);

        int *A = (int *)malloc(N * sizeof(int));
        int *B = (int *)malloc(N * sizeof(int));

        for (int i = 0; i < N; i++) {
            scanf("%d", &A[i]);
        }
        for (int i = 0; i < N; i++) {
            scanf("%d", &B[i]);
        }

        // Count the number of states that candidate A is already winning.
        int wins = 0;
        // This array will hold the extra votes needed for states where A isn't winning.
        int *cost = (int *)malloc(N * sizeof(int));
        int costCount = 0;

        for (int i = 0; i < N; i++) {
            if (A[i] > B[i]) {
                wins++;
            } else {
                // Candidate A requires (B[i] - A[i] + 1) votes to win this state.
                cost[costCount++] = (B[i] - A[i] + 1);
            }
        }

        // To win overall, candidate A must win more than half the states.
        int winGoal = (N + 1) / 2;

        if (wins >= winGoal) {
            printf("YES\n");
        } else {
            // Sort the required extra votes in non-decreasing order.
            qsort(cost, costCount, sizeof(int), cmp);

            // Determine how many additional states we need to flip.
            int needed = winGoal - wins;

            for (int i = 0; i < costCount && needed > 0; i++) {
                if (X >= cost[i]) {
                    X -= cost[i];
                    needed--;
                }
            }

            if (needed == 0) {
                printf("YES\n");
            } else {
                printf("NO\n");
            }
        }

        // Free allocated memory
        free(A);
        free(B);
        free(cost);
    }

    return 0;
}

