                            ops += abs(counts[p][1] - (p == j ? 1 : 0));
                            ops += abs(counts[p][2] - (p == k ? 1 : 0));
                        }
                        min_ops = std::min(min_ops, ops / 2);
                    }
                }
            }
        }

