class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int maxElement = *max_element(nums.begin(), nums.end());
        int n = nums.size();
        vector<int> compress;
        for (int i = 0; i < n; i++) {
            compress.push_back(nums[i] == maxElement ? 1 : 0);
        }

        long long res = 0;
        int count = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            if (compress[right] == 1) {
                count++;
            }
            while (count >= k) {
                res += n - right;
                if (compress[left] == 1) {
                    count--;
                }
                left++;
            }
        }
        return res;
    }
};
