class Solution {
public:
    vector<int> numberGame(vector<int>& nums) {
        vector<int> ans;
        int left = 0, right = nums.size() - 1;
        while (left < right) {
            int alice = *min_element(nums.begin() + left, nums.begin() + right + 1);
            int bob = *min_element(nums.begin() + left, nums.begin() + right + 1);
            if (alice == bob) {
                ans.push_back(alice);
                ans.push_back(bob);
            } else {
                int idx_alice = distance(nums.begin(), find(nums.begin() + left, nums.begin() + right + 1, alice));
                int idx_bob = distance(nums.begin(), find(nums.begin() + left, nums.begin() + right + 1, bob));
                if (idx_alice < idx_bob) {
                    ans.push_back(bob);
                    ans.push_back(alice);
                } else {
                    ans.push_back(alice);
                    ans.push_back(bob);
                }
            }
            left += 1;
            right -= 1;
        }
        return ans;
    }
};

