class Solution {
public:
    vector<int> lexicographicallySmallestArray(vector<int>& nums, int limit) {
        // Create array of indexes and sort it based on values from nums
        vector<int> indexes(nums.size());
        iota(indexes.begin(), indexes.end(), 0);
        sort(indexes.begin(), indexes.end(), [&](auto a, auto b) {
            return nums[a] < nums[b];
        });

        // Subset of numbers which has difference between adjacent pairs <= limit
        vector<int> subset;
        subset.reserve(nums.size());
        subset.push_back(nums[indexes[0]]);
        for (int lo = 0, hi = 1; hi <= indexes.size(); hi++) {
            // Check if we reached to end of the subset. 
            if (hi == indexes.size() || nums[indexes[hi]] - nums[indexes[hi-1]] > limit) {
                // Now we want to sort indexes in range lo-hi in decreasing order
                // After that we can change elements in nums which are in same subset by setting highest element from subset to highest index from subset
                sort(begin(indexes) + lo, begin(indexes) + hi, greater<int>());
                for (int i = lo; i < hi; i++) {
                    nums[indexes[i]] = subset.back();
                    subset.pop_back();
                }
                lo = hi;
            }
            if (hi < indexes.size())
                subset.push_back(nums[indexes[hi]]);
        }

        return nums;
    }
};

