class Solution {
public:
    vector<int> lexicographicallySmallestArray(vector<int>& nums, int limit) {
        int n = nums.size();
        vector<int> ans = nums;
        sort(ans.begin(), ans.end());
        vector<int> pos(n);
        for (int i = 0; i < n; i++) {
            pos[i] = i;
        }
        UnionFind uf(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n && ans[j] - ans[i] <= limit; j++) {
                uf.union(pos[i], pos[j]);
            }
        }
        for (int i = 0; i < n; i++) {
            ans[uf.find(i)] = nums[i];
        }
        return ans;
    }
};

class UnionFind {
public:
    vector<int> parent;
    UnionFind(int n) {
        parent.resize(n);
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }
    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }
    void union(int x, int y) {
        int rootx = find(x);
        int rooty = find(y);
        if (rootx != rooty) {
            parent[rootx] = rooty;
        }
    }
};

