        iota(indexes.begin(), indexes.end(), 0);
        sort(indexes.begin(), indexes.end(), [&](auto a, auto b) {
            return nums[a] < nums[b];
        });

        vector<int> subset;
        subset.reserve(n);
        subset.push_back(nums[indexes[0]]);
        for (int lo = 0, hi = 1; hi <= n; hi++) {
