        // Since a < b, we have a < K - a, i.e. 2a < K.
        // Hence a must be in: [ max(1, K-N), floor((K-1)/2) ]
        int lower = max(1, K - N);
        int upper = (K - 1) / 2; // floor((K-1)/2)
        int m = 0;
        if (lower <= upper)
            m = upper - lower + 1;

