        pow2Arr[i] = (2 * pow2Arr[i - 1]) % MOD;
    }
}

// Compute nCr modulo MOD (assumes 0 <= r <= n)
long long nCr(int n, int r) {
    if (r < 0 || r > n)
        return 0;
    return ((fact[n] * invfact[r]) % MOD * invfact[n - r]) % MOD;
}

