        // 1 <= a < b <= N  and  a + b = K.
        // Since a < b, we have a < K - a, i.e. 2a < K.
        // Hence a must be in: [ max(1, K-N), floor((K-1)/2) ]
        int lower = max(1, K - N);
        int upper = (K - 1) / 2; // floor((K-1)/2)
        int m = 0;
        if (lower <= upper)
            m = upper - lower + 1;

        // If no valid pair exists, then answer is 0.
        if (m <= 0) {
            cout << 0 << "\n";
            continue;
        }

        // Use inclusion-exclusion:
        // answer = sum_{j=1}^{m} (-1)^(j+1) * C(m, j) * 2^j * (N - j)!
        long long ans = 0;
