const long long MOD = 1000000007;

// The maximum value of N is 100,000.
const int MAX = 100000;
vector<long long> fact(MAX + 1), invfact(MAX + 1), pow2Arr(MAX + 1);

// Fast modular exponentiation (mod MOD)
long long modExp(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

// Precompute factorials, inverse factorials and powers of 2 up to MAX.
