#include <bits/stdc++.h>
using namespace std;
using ll = long long;

// Check if it's possible to achieve unsavoriness W
// with at most K temperature changes (i.e. <= K+1 segments).
bool feasible(const vector<ll>& A, ll W, int K) {
    int segments = 1;
    ll cur_min = A[0], cur_max = A[0];
    for (int i = 1, n = A.size(); i < n; ++i) {
        cur_min = min(cur_min, A[i]);
        cur_max = max(cur_max, A[i]);
        // If the current segment's range exceeds 2W, start a new segment
        if (cur_max - cur_min > 2*W) {
            ++segments;
            cur_min = cur_max = A[i];
        }
    }
    return segments <= K + 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int N, K;
        cin >> N >> K;
        vector<ll> A(N);
        for (int i = 0; i < N; ++i)
            cin >> A[i];

        // If you can change at every step, you can match A exactly.
        if (K >= N - 1) {
            cout << 0 << "\n";
            continue;
        }

        // Determine the search range: 0 … max(A)-min(A)
        ll mn = *min_element(A.begin(), A.end());
        ll mx = *max_element(A.begin(), A.end());
        ll low = 0, high = mx - mn;

        // Binary search for the minimal W
        while (low < high) {
            ll mid = (low + high) / 2;
            if (feasible(A, mid, K))
                high = mid;
            else
                low = mid + 1;
        }

        cout << low << "\n";
    }
    return 0;
}

