                sum--;

            if(prefix.find(sum) != prefix.end()) {
                for(auto &prevIndex: prefix[sum]) {
                    long long count = (i - prevIndex) / 2;

                    if((count * count) % k == 0)
                        cnt++;
                }
            }

            prefix[sum].push_back(i);
        }

        return cnt;
    }
};

