class Solution {
public:
    int update(int i, int val, vector<int>& fenwick) {
        while (i < fenwick.size()) {
            fenwick[i] += val;
            i += i & -i;
        }
    }

    int query(int i, vector<int>& fenwick) {
        int sum = 0;
        while (i > 0) {
            sum += fenwick[i];
            i -= i & -i;
        }
        return sum;
    }

    bool isVowel(char ch) {
        return (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u');
    }

    int beautifulSubstrings(string s, int k) {
        int n = s.size();
        vector<int> cnt(n + 1, 0);
        for (int i = 0; i < n; i++) {
            cnt[i + 1] = cnt[i] + (isVowel(s[i]) ? 1 : -1);
        }

        vector<int> sorted_cnt = cnt;
        sort(sorted_cnt.begin(), sorted_cnt.end());
        int unique_cnt = unique(sorted_cnt.begin(), sorted_cnt.end()) - sorted_cnt.begin();

        vector<int> mapping(unique_cnt + 1, 0);
        for (int i = 0; i < unique_cnt; i++) {
            mapping[sorted_cnt[i]] = i + 1;
        }

        for (int i = 1; i <= n; i++) {
            cnt[i] = mapping[cnt[i]];
        }

        vector<int> fenwick(unique_cnt + 1, 0);
        int res = 0;
        for (int i = 0; i < n; i++) {
            int c = cnt[i + 1];
            res += query(c, fenwick);
            update(c, 1, fenwick);
        }
        return res;
    }
};

