class Solution {
public:
    int numberOfGoodPartitions(vector<int>& nums) {
        unordered_map<int, pair<int, int>> intervals;
        for (int i = 0; i < nums.size(); ++i) {
            auto it = intervals.find(nums[i]);
            if (it == intervals.end()) {
                intervals[nums[i]] = {i, i};
            } else {
                intervals[nums[i]].second = i;
            }
        }

        vector<pair<int, int>> intervals_sorted;
        intervals_sorted.reserve(intervals.size());
        for (auto [_, interval]: intervals) {
            intervals_sorted.push_back(interval);
        }
        sort(intervals_sorted.begin(), intervals_sorted.end());
        int left = 0;
        for (int right = 1; right < intervals_sorted.size(); ++right) {
            if (intervals_sorted[left].second < intervals_sorted[right].first) {
                ++left;
                intervals_sorted[left] = intervals_sorted[right];
                continue;
            }

            intervals_sorted[left].second = max(intervals_sorted[left].second, intervals_sorted[right].second);
        }
        int ans = 1;
        while (left--) {
            ans *= 2;
            ans %= 1000000007;
        }
        return ans;
    }
};

