class Solution {
public:
    int minimumOperationsToMakeEqual(int x, int y) {
        if (y >= x) return y - x;

        queue<int> bfs;
        bfs.push(x);
        int step = 0;
        unordered_set<int> vis;
        vis.insert(x);

        while (!bfs.empty()) {
            int size = bfs.size();
            for (int i = 0; i < size; i++) {
                int curr = bfs.front();
                bfs.pop();

                if (curr == y) return step;

                // Divide by 11
                if (curr % 11 == 0 && vis.find(curr / 11) == vis.end()) {
                    vis.insert(curr / 11);
                    bfs.push(curr / 11);
                }

                // Divide by 5
                if (curr % 5 == 0 && vis.find(curr / 5) == vis.end()) {
                    vis.insert(curr / 5);
                    bfs.push(curr / 5);
                }

                // Increment
                if (vis.find(curr + 1) == vis.end()) {
                    vis.insert(curr + 1);
                    bfs.push(curr + 1);
                }

                // Decrement
                if (curr > 1 && vis.find(curr - 1) == vis.end()) {
                    vis.insert(curr - 1);
                    bfs.push(curr - 1);
                }
            }
            step++;
        }
        return -1; // This line will never be reached given the constraints of the problem.
    }
};

