constexpr int MAX = 20010;

int cnt[MAX];
i64 c[MAX], dp[MAX][2][4], buf[8];
vector<int> adj[MAX];

void Combine(const i64* a, const i64* b, i64* c) {
  std::copy(a, a + 3, buf);
  std::copy(b, b + 3, buf + 3);
  std::sort(buf, buf + 6, std::greater<i64>());
  std::copy(buf, buf + 3, c);
}

void DFS(int x, int p) {
  cnt[x] = 1;
  dp[x][0][0] = c[x] < 0 ? -1 : c[x];
  dp[x][0][1] = -1;
  dp[x][0][2] = -1;
  dp[x][1][0] = c[x] < 0 ? -c[x] : -1;
  dp[x][1][1] = -1;
  dp[x][1][2] = -1;
  for (int y : adj[x]) {
    if (y == p) {
      continue;
    }
    DFS(y, x);
    cnt[x] += cnt[y];
    Combine(dp[x][0], dp[y][0], dp[x][0]);
    Combine(dp[x][1], dp[y][1], dp[x][1]);
  }
}

