        c[i] = cost[i];
        std::vector<int>().swap(adj[i]);
      }
      for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
      }
      DFS(0, -1);
      std::vector<i64> ret(n);
      for (int i = 0; i < n; ++i) {
        if (cnt[i] < 3) {
          ret[i] = 1;
        } else {
          ret[i] = 0;
          if (dp[i][0][2] > 0) {
            ret[i] = std::max(ret[i], dp[i][0][0] * dp[i][0][1] * dp[i][0][2]);
          }
          if (dp[i][0][0] > 0 && dp[i][1][1] > 0) {
            ret[i] = std::max(ret[i], dp[i][0][0] * dp[i][1][0] * dp[i][1][1]);
          }
        }
      }
      return ret;
    }
};

