    vector<long long> placedCoins(vector<vector<int>>& edges, vector<int>& cost) {
        int n = cost.size();
        vector<i64> c(n);
        for (int i = 0; i < n; ++i) {
            c[i] = cost[i];
        }

        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            int u = e[0], v = e[1];
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        vector<int> order(n), parent(n, -1);
        order[0] = 0;
        int l = 0, r = 1;
        while (l < r) {
            int x = order[l++];
            for (int y : adj[x]) {
                if (y == parent[x]) continue;
                parent[y] = x;
                order[r++] = y;
            }
        }

        vector<i64> coin(n);
        vector<vector<i64>> dp(n, vector<i64>(3, -1));
        for (int i = n - 1; i >= 0; --i) {
            int x = order[i];
            if (i == n - 1 || parent[x] == -1) {
                dp[x][0] = c[x] < 0 ? -1 : c[x];
                dp[x][1] = -1;
                dp[x][2] = -1;
            } else {
                dp[x] = dp[parent[x]];
            }

            int subtree_size = 1;
            for (int y : adj[x]) {
                if (y == parent[x]) continue;
                subtree_size += order.size() - l;
            }

            if (subtree_size < 3) {
                coin[x] = 1;
            } else {
                sort(dp[x].rbegin(), dp[x].rend());
                coin[x] = dp[x][0] > 0 ? dp[x][0] * dp[x][1] * dp[x][2] : 0;
            }
        }

        return coin;
    }
};

