    int countPrefixSuffixPairs(vector<string>& words) {
        int cnt = 0;
        for (int i = 0; i < words.size(); ++i) {
            for (int j = i + 1; j < words.size(); ++j) {
                if (isPrefixAndSuffix(words[i], words[j])) {
                    ++cnt;
                }
            }
        }
        return cnt;
    }

    bool isPrefixAndSuffix(const string& s, const string& t) {
        if (s.size() > t.size()) {
            return false;
        }
        return t.find(s, 0) != string::npos && t.rfind(s) != string::npos;
    }
};

class Solution {
public:
    int countPrefixSuffixPairs(vector<string>& words) {
        int n = words.size();
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (words[i].size() > words[j].size()) continue;
                bool isPrefix = true, isSuffix = true;
                for (int k = 0; k < words[i].size(); k++) {
                    if (words[i][k] != words[j][k]) {
                        isPrefix = false;
                        break;
                    }
                }
                for (int k = 0; k < words[i].size(); k++) {
                    if (words[i][words[i].size() - 1 - k] != words[j][words[j].size() - 1 - k]) {
                        isSuffix = false;
                        break;
                    }
                }
                if (isPrefix && isSuffix) cnt++;
            }
        }
        return cnt;
    }
};

