class Solution {
    vector<int> calcLps(string& word) {
        int n = word.size();
        vector<int> lps(n, 0);
        int len = 0;
        lps[0] = 0;

        int i = 1;
        while (i < n) {
            if (word[i] == word[len]) {
                len++;
                lps[i] = len;
                i++;
            } else {
                if (len != 0) {
                    len = lps[len - 1];
                } else {
                    lps[i] = 0;
                    i++;
                }
            }
        }
        return lps;
    }

public:
    int minimumTimeToInitialState(string s, int k) {
        ios_base::sync_with_stdio(0);
        cin.tie(0);
        cout.tie(0);

        int n = s.length();

        vector<int> lps = calcLps(s);

        // maxlps stores the longest prefix of the entire string that is also a suffix.
        int maxlps = lps.back();

        // The while loop tries to find the largest repeating prefix-suffix such
        // that the leftover portion (n - maxlps) can be evenly divided by k. 
        // If (n - maxlps) % k != 0, it means that the current maxlps doesn't allow
        // a complete cycle that matches k, so maxlps is reduced to 
        // lps[maxlps - 1].

        while (maxlps > 0 && (n - maxlps) % k != 0) {
            maxlps = lps[maxlps - 1];
        }

        if ((n - maxlps) % k == 0) {
            return (n - maxlps) / k;
        }
        return ceil(n / (double)k);
    }
};

