class Solution {
public:
    // time/space: O(1)/O(1)
    int minMovesToCaptureTheQueen(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        // try to move the rook in 1 step
        if (xRook == xQueen) {
            // check if the bishop is block the vertical way
            if ((xRook == xBishop) && 
                (((yRook < yBishop) && (yBishop < yQueen)) ||
                ((yQueen < yBishop) && (yBishop < yRook)))) {}
            else return 1;
        }
        if (yRook == yQueen) {
            // check if the bishop is block the horizontal way
            if ((yRook == yBishop) && 
                (((xRook < xBishop) && (xBishop < xQueen)) ||
                ((xQueen < xBishop) && (xBishop < xRook)))) {}
            else return 1;
        }

        // try to move the bishop in 1 step
        int dxQ2B = xQueen - xBishop;
        int dyQ2B = yQueen - yBishop;
        if (abs(dxQ2B) == abs(dyQ2B)) {
            int dxR2B = xRook - xBishop;
            int dyR2B = yRook - yBishop;
            // check if the rock is block the bishop's way
            if (isSameSlope(dxQ2B, dyQ2B, dxR2B, dyR2B) &&
                isSameDirection(dxQ2B, dyQ2B, dxR2B, dyR2B) &&
                (abs(dxQ2B) > abs(dxR2B)) &&
                (abs(dyQ2B) > abs(dyR2B))) {}
            else return 1;
        }

        return 2;
    }
private:
    bool isSameSlope(int dx1, int dy1, int dx2, int dy2) {
        return ((dx1 * dy2) == (dx2 * dy1));
    }
    bool isSameDirection(int dx1, int dy1, int dx2, int dy2) {
        if ((dx1 * dx2) < 0) return false;
        if ((dy1 * dy2) < 0) return false;
        return true;
    }
};

