class Solution {
public:
    int minMovesToCaptureTheQueen(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        if (xRook == xQueen || yRook == yQueen) {
            if (isBlocked(yRook, xRook, yBishop, xBishop, yQueen, xQueen)) {
                return 2;
            }
            return 1;
        }
        if (abs(xQueen - xBishop) == abs(yQueen - yBishop)) {
            if (isOnBishopPath(yRook, xRook, yBishop, xBishop, yQueen, xQueen)) {
                return 2;
            }
            return 1;
        }
        return 2;
    }
private:
    bool isBlocked(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        if (xRook == xQueen) {
            return (yRook < yQueen && yBishop > yRook && yBishop < yQueen) || (yRook > yQueen && yBishop < yRook && yBishop > yQueen);
        }
        return (yRook == yQueen && ((xRook < xQueen && xBishop > xRook && xBishop < xQueen) || (xRook > xQueen && xBishop < xRook && xBishop > xQueen)));
    }
    bool isOnBishopPath(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        int dx = xQueen - xBishop;
        int dy = yQueen - yBishop;
        if (abs(dx) != abs(dy)) {
            return false;
        }
        int dxR = xRook - xBishop;
        int dyR = yRook - yBishop;
        return dx * dyR == dy * dxR && (dx * dxR > 0) && (dy * dyR > 0) && abs(dx) > abs(dxR);
    }
};

