public:
    int minMovesToCaptureTheQueen(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        // Check if rook can capture queen in one move
        if (xRook == xQueen || yRook == yQueen) return 1;

        // Check if bishop can capture queen in one move
        if (abs(xQueen - xBishop) == abs(yQueen - yBishop)) {
            // Check if rook blocks bishop's path
            if (!(xRook == xBishop || yRook == yBishop) ||
                (xRook * (yQueen - yBishop) != (xQueen - xBishop) * yRook &&
                 xBishop * (yQueen - yRook) != (yBishop - yRook) * xQueen)) {
