class Solution {
public:
    int minMovesToCaptureTheQueen(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        // Check if rook can capture queen in 1 move
        if (xRook == xQueen || yRook == yQueen) {
            if (!isBlockedByBishop(xRook, yRook, xBishop, yBishop, xQueen, yQueen)) {
                return 1;
            }
        }
        // Check if bishop can capture queen in 1 move
        if (abs(xQueen - xBishop) == abs(yQueen - yBishop)) {
            if (!isBlockedByRook(xRook, yRook, xBishop, yBishop, xQueen, yQueen)) {
                return 1;
            }
        }
        return 2;
    }
private:
    bool isBlockedByBishop(int xRook, int yRook, int xBishop, int yBishop, int xQueen, int yQueen) {
        int dx = xQueen - xBishop;
        int dy = yQueen - yBishop;
        if (abs(dx) != abs(dy)) return false;
        int x = xBishop + dx;
        int y = yBishop + dy;
        while (x != xQueen || y != yQueen) {
            if (x == xRook && y == yRook) return true;
            x += dx > 0 ? 1 : -1;
            y += dy > 0 ? 1 : -1;
        }
        return false;
    }
    bool isBlockedByRook(int xRook, int yRook, int xBishop, int yBishop, int xQueen, int yQueen) {
        if (xRook == xBishop) {
            int y = yBishop;
            while (y != yQueen) {
                y += yQueen > yBishop ? 1 : -1;
                if (y == yRook) return true;
            }
        } else if (yRook == yBishop) {
            int x = xBishop;
            while (x != xQueen) {
                x += xQueen > xBishop ? 1 : -1;
                if (x == xRook) return true;
            }
        }
        return false;
    }
};

