public:
    int minMovesToCaptureTheQueen(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        if (xRook == xQueen || yRook == yQueen) {
            if (xRook == xQueen) {
                return checkRook(yRook, xRook, yBishop, xBishop, yQueen, xQueen);
            } else {
                return checkRook(yRook, xRook, yBishop, xBishop, yQueen, xQueen);
            }
        }
        if (abs(xQueen - xBishop) == abs(yQueen - yBishop)) {
            return checkBishop(yRook, xRook, yBishop, xBishop, yQueen, xQueen);
        }
        return 2;
    }
private:
    int checkRook(int yRook, int xRook, int yBishop, int xBishop, int yQueen, int xQueen) {
        if (yRook < yBishop && yBishop < yQueen || yQueen < yBishop && yBishop < yRook) {
            if (xRook == xBishop) return 2;
        } else {
            if (xRook == xBishop && yRook != yBishop) return 2;
            return 1;
        }
        return 1;
