        vector<bool> ans;
        set<int> st;

        for(int i = 0; i < n; i++){
            if(i < n/2){
                for(int j = 0; j < 26; j++) a[i+1][j] = a[i][j];
                a[i+1][s[i]-'a']++;
            }
            else{
                for(int j = 0; j < 26; j++) b[i+1-n/2][j] = b[i-n/2][j];
                b[i+1-n/2][s[n-1-(i-n/2)]-'a']++;
