            if(y1 < y2 && !checkAvailable(max(y1+1, x2), y2, x2, y2, false))
                val = false;
            if(y2 < y1 && !checkAvailable(x1, y1, max(y2+1, x1), y1, true))
                val = false;

            ans.push_back(val);
