class SegmentTree {
public:
    vector<vector<int>> tree;
    int n;

    SegmentTree(string& s) {
        n = s.size() / 2;
        tree.resize(4 * n);
        build(s, 0, 0, n - 1);
    }

    void build(string& s, int node, int start, int end) {
        if (start == end) {
            tree[node][s[start] - 'a'] = 1;
        } else {
            int mid = (start + end) / 2;
            build(s, 2 * node + 1, start, mid);
            build(s, 2 * node + 2, mid + 1, end);
            for (int i = 0; i < 26; i++) {
                tree[node][i] = tree[2 * node + 1][i] + tree[2 * node + 2][i];
            }
        }
    }

    vector<int> query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) {
            return vector<int>(26, 0);
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        vector<int> p1 = query(2 * node + 1, start, mid, l, r);
        vector<int> p2 = query(2 * node + 2, mid + 1, end, l, r);
        vector<int> res(26, 0);
        for (int i = 0; i < 26; i++) {
            res[i] = p1[i] + p2[i];
        }
        return res;
    }

    void update(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node][val] = 1;
        } else {
            int mid = (start + end) / 2;
            if (idx <= mid) {
                update(2 * node + 1, start, mid, idx, val);
            } else {
                update(2 * node + 2, mid + 1, end, idx, val);
            }
            for (int i = 0; i < 26; i++) {
                tree[node][i] = tree[2 * node + 1][i] + tree[2 * node + 2][i];
            }
        }
    }
};

