        sort(access_times.begin(), access_times.end(), [](const auto& a, const auto& b) {
            if (a[0] == b[0]) return a[1] < b[1];
            return a[0] < b[0];
        });

        unordered_map<string, vector<int>> employee_times;
        for (const auto& [employee, time] : access_times) {
            int time_int = stoi(time);
            employee_times[employee].push_back(time_int);
        }

        vector<string> high_access_employees;
        for (const auto& [employee, times] : employee_times) {
            if (times.size() < 3) continue;

            int count = 0;
            for (int i = 0; i < times.size() - 2; ++i) {
                if (times[i + 2] - times[i] < 100) {
                    count++;
                    if (count >= 1) {
                        high_access_employees.push_back(employee);
                        break;
                    }
                } else {
                    count = 0;
                }
            }
        }

        return high_access_employees;
    }
};

