class Solution {
public:
    long long minimumCost(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        long long median = n % 2 ? nums[n / 2] : (nums[n / 2 - 1] + nums[n / 2]) / 2LL;
        stringstream ss;
        ss << median;
        string str = ss.str();
        int len = str.size();
        long long pal = stoll(str);
        vector<long long> palindromes = {pal - 1, pal, pal + 1};
        palindromes.push_back(stoll(string(max(1, len - 1), '9')));
        long long res = LLONG_MAX;
        for(long long p : palindromes){
            long long cost = 0;
            for(int num : nums){
                cost += abs(num - p);
            }
            res = min(res, cost);
        }
        return res;
    }
};

