public:
    long dfs(int i, string &s, string &t) {
        if (i == s.size())
            return 0; // base
        if (dp[i] != -1)
            return dp[i]; // memo

        long ret = s[i] == t[i] ? dfs(i + 1, s, t) : inf;
        TrieNode *l = root;
        TrieNode *r = root;

        for (int j = i; j < s.size(); j++) {
            // Trie move
            advance(l, s[j]);
            advance(r, t[j]);
            if (l == NULL || r == NULL)
                break ; // none matches to be found further

            if (l->id == -1 || r->id == -1)
                continue ; // not a word yet

            int x = l->id;
            int y = r->id;
            if (d[x][y] == inf)
                continue ; // no conversion

            ret = min(ret, d[x][y] + dfs(j + 1, s, t));
        }
        return dp[i] = ret;
    }
