    string getSmallestString(string s, int k) {
        int n=s.size();
        // let the smallest string of size n be "aaa....n"
        string t="";
        for(int i=0;i<n;i++){
            t+='a';
        }
        int i=0;
        while(i<n && k>0){
            if(s[i]==t[i]){
                i++;
                continue;
            }
            char ch=s[i];
            char c=t[i];
            int direct_dis=(ch-'a')- (c-'a');
            int reverse_dis=26-(ch-'a')+(c-'a');
            int dis=min(direct_dis,reverse_dis);
            // minimum distance is also greater than k than we have to replace the char
            if(k<dis){
                // replacing the char in t[i]
                t[i]=((ch-'a')-k)+'a';
                // no k left
                k=0;
            }
            else{
                k-=dis;
            }
            i++;
        }
        // for testcase lol we have to again travere the s.
        while(k==0 && i<n ){
            t[i]=s[i];
            i++;
        }
        return t;
    }
};

