            if (k == 0) break;
            int dis = min((s[i] - 'a'), 26 - (s[i] - 'a'));
            int replaceDis = min(dis, k);
            t[i] = 'a' + (s[i] - 'a' - replaceDis + 26) % 26;
            k -= replaceDis;
        }
        return t;
    }
};

