class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> b_indices;
        b_indices.reserve(s.size() / b.size() + 1);
        for (int index = s.find(b, 0); index != string::npos; index = s.find(b, index + 1)) {
            b_indices.push_back(index);
        }
        vector<int> result;
        result.reserve(s.size() / a.size() + 1);
        for (int index = s.find(a, 0); index != string::npos; index = s.find(a, index + 1)) {
            auto pos = lower_bound(b_indices.begin(), b_indices.end(), index - k);
            if (pos != b_indices.end() && abs(index - *pos) <= k) {
                result.push_back(index);
            }
        }
        return result;
    }
};

class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> bIndices{};
        int bStart = 0;
        while (bStart < s.size()) {
            size_t index = s.find(b, bStart);
            if (index == string::npos) break;
            bIndices.push_back(index);
            bStart = index + 1;
        }

        vector<int> result{};
        int aStart = 0;
        while (aStart < s.size()) {
            size_t index = s.find(a, aStart);
            if (index == string::npos) break;
            auto pos = lower_bound(bIndices.begin(), bIndices.end(), index - k);
            if (pos != bIndices.end() && index - bIndices[pos - bIndices.begin()] <= k) {
                result.push_back(index);
            }
            aStart = index + 1;
        }
        return result;
    }
};

class Solution {
public:
    vector<int> beautifulIndices(string s, string a, string b, int k) {
        int n = s.size();
        vector<int> aIndices, bIndices;
        for (int i = 0; i <= n - a.size(); i++) {
            if (s.substr(i, a.size()) == a) {
                aIndices.push_back(i);
            }
        }
        for (int i = 0; i <= n - b.size(); i++) {
            if (s.substr(i, b.size()) == b) {
                bIndices.push_back(i);
            }
        }
        vector<int> result;
        int bIndex = 0;
        for (int aIndex : aIndices) {
            while (bIndex < bIndices.size() && bIndices[bIndex] < aIndex - k) {
                bIndex++;
            }
            if (bIndex < bIndices.size() && bIndices[bIndex] <= aIndex + k) {
                result.push_back(aIndex);
            }
        }
        return result;
    }
};

