class Solution {
public:
    vector<int> compute_prefix_function(string& s) {
        int n = s.size();
        vector<int> pi(n, 0);
        int j = 0;
        for (int i = 1; i < n; i++) {
            while (j > 0 && s[i] != s[j]) j = pi[j - 1];
            if (s[i] == s[j]) j++;
            pi[i] = j;
        }
        return pi;
    }

    vector<int> kmp(string& s, string& p) {
        string concat = p + "#" + s;
        vector<int> pi = compute_prefix_function(concat);
        vector<int> matches;
        for (int i = p.size() + 1; i < concat.size(); i++) {
            if (pi[i] == p.size()) matches.push_back(i - p.size() - 1);
        }
        return matches;
    }

    vector<int> beautifulIndices(string s, string a, string b, int k) {
        vector<int> amat = kmp(s, a), bmat = kmp(s, b);
        vector<int> ans;
        for (auto& i : amat) {
            auto it = lower_bound(bmat.begin(), bmat.end(), i - k);
            if (it != bmat.end() && *it <= i + k) ans.push_back(i);
        }
        return ans;
    }
};

