using ll = long long;
class UnionFind {
public:
    vector<int> size, parent;
    UnionFind(int n) : size(n, 1), parent(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int p) {
        if (parent[p] != p) parent[p] = find(parent[p]);
        return parent[p];
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (size[a] > size[b]) swap(a, b);
        parent[a] = b;
        size[b] += size[a];
        return true;
    }
    bool connected(int a, int b) {
        return find(a) == find(b);
    }
    int components() {
        int cnt = 0;
        for (int i = 0; i < parent.size(); ++i) {
            if (parent[i] == i) ++cnt;
        }
        return cnt;
    }
};
class Solution {
public:
    ll counting(int x, vector<int>& nums){
        UnionFind uf(nums.size());
        ll n = nums.size(), ans = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                uf.unite(i, j);
                if (uf.components() > x) break;
                ans++;
            }
        }
        return ans;
    }
    int medianOfUniquenessArray(vector<int>& nums) {
        ll n = nums.size();
        ll p = (1 + n) * n / 2;
        if (p & 1) p = p / 2 + 1;
        else p = p / 2;
        int l = 1, r = n;
        while (l <= r) {
            int m = l + ((r - l) >> 1);
            ll c = counting(m, nums);
            if (c >= p) r = m - 1;
            else l = m + 1;
        }
        return r + 1;
    }
};
