public:
    int findWinningPlayer(vector<int>& skills, int k) {
        int wins = 0;
        auto max = skills.begin();
        for(auto it = skills.begin() + 1; it != skills.end() && wins < k; ++it) {
            if(*max > *it) {
                ++wins;
            } else {
                wins = 1;
                max = it;
            }
        }
        return std::distance(skills.begin(), max);
    }
