// Fast exponentiation (Binary Exponentiation)
int power(int a, int b, int m = MOD) {
    int res = 1;
    while (b) {
        if (b & 1) res = (res * a) % m;
        a = (a * a) % m;
        b >>= 1;
    }
    return res;
}

// ---------- PRIME UTILITIES ----------
// Sieve of Eratosthenes to find all primes up to `n`
vector<int> sieve(int n) {
    vector<bool> is_prime(n + 1, true);
    vector<int> primes;
    is_prime[0] = is_prime[1] = false;

    for (int i = 2; i * i <= n; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= n; j += i)
                is_prime[j] = false;
        }
    }

    for (int i = 2; i <= n; i++) {
        if (is_prime[i]) primes.push_back(i);
    }
    return primes;
}


// Check if a number is prime
bool isprime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

// ---------- SEARCHING & SORTING ----------
// binary search
int bs(vector<int> &arr, int target) {
    int lo = 0, hi = sz(arr) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1; // Not found
}

// Custom comparator for sorting in descending order
bool cmp_desc(int a, int b) { return a > b; }


// ---------- MAIN SOLUTION ----------


void solve() {
    int N;
    long long L, R;
    cin >> N >> L >> R;
    vector<int> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    if (N == 1) {
        cout << (L <= 1 && 1 <= R ? "YES" : "NO") << "\n";
        return;
    }

    sort(A.begin(), A.end());

    int zero =0;
    long long product = 1;
    for (int i = 0; i < N && !zero; ++i) {
        for (int j = i + 1; j < N; ++j) {
            long long xor_val = A[i] ^ A[j];
            if (xor_val == 0) {
                zero = 1;
                break;
            }
            if (product > R / xor_val) {
                product = R + 1;
                break;
            }
            product *= xor_val;
        }
    }

    if (zero) product = 0;

    cout << (L <= product && product <= R ? "YES" : "NO") <<endl;


}

