public:
    int maxScore(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> dp(m, vector<int>(n));
        dp[m-1][n-1] = grid[m-1][n-1];
        int ans = INT_MIN;
        for (int i = m-2; i >= 0; --i) {
            dp[i][n-1] = max(grid[i][n-1], dp[i+1][n-1]);
            ans = max(ans, dp[i][n-1] - grid[i][n-1]);
        }
        for (int j = n-2; j >= 0; --j) {
            dp[m-1][j] = max(grid[m-1][j], dp[m-1][j+1]);
            ans = max(ans, dp[m-1][j] - grid[m-1][j]);
        }
        for (int i = m-2; i >= 0; --i) {
            for (int j = n-2; j >= 0; --j) {
                dp[i][j] = max(grid[i][j], max(dp[i+1][j], dp[i][j+1]));
                ans = max(ans, dp[i][j] - grid[i][j]);
            }
        }
        return ans;
    }
};

class Solution {
public:
    int maxScore(vector<vector<int>>& a) {
        int n = a.size(), m = a[0].size(), ans = INT_MIN;
        vector<int> min_val(m, INT_MAX), max_val(m, INT_MIN);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i == 0) {
                    min_val[j] = a[i][j];
                    max_val[j] = a[i][j];
                } else {
                    min_val[j] = min(min_val[j], a[i][j]);
                    max_val[j] = max(max_val[j], a[i][j]);
