class Solution {
public:
    long long sumDigitDifferences(vector<int>& nums) {
        int cnt[10] = {0};
        int n = nums.size();
        int digits = to_string(nums[0]).size();
        for (int i = 0; i < digits; i++) {
            memset(cnt, 0, sizeof(cnt));
            for (auto& x : nums) {
                cnt[x / pow(10, digits - i - 1) % 10]++;
            }
            long long res = 0;
            for (int j = 0; j < 10; j++) {
                for (int k = j + 1; k < 10; k++) {
                    res += cnt[j] * cnt[k];
                }
            }
            ans += res;
        }
        return ans;
    }
};

