    long long sumDigitDifferences(vector<int>& nums) {
        int n = nums.size();
        int cntDigits[10] = {0};
        for (auto num : nums) {
            int digit;
            while (num) {
                digit = num % 10;
                cntDigits[digit]++;
                num /= 10;
            }
        }

        long long ans = 0;
        for (int i = 0; i < 10; i++) {
            ans += cntDigits[i] * (n - cntDigits[i]);
        }
        return ans;
    }
};

class Solution {
public:
    long long sumDigitDifferences(vector<int>& nums) {
        constexpr int MAX_DIGIT = 10;
        const vector<vector<int>> digitDiffLookup = getDigitDiffLookup(MAX_DIGIT);
        int numDigits = to_string(nums[0]).size();
        vector<int> digitCounts(numDigits, vector<int>(MAX_DIGIT, 0));
        for (int num : nums) {
            string numStr = to_string(num);
            for (int i = 0; i < numDigits; ++i) {
                digitCounts[i][numStr[i] - '0']++;
            }
        }
        long long totalDiff = 0;
        for (int i = 0; i < numDigits; ++i) {
            for (int j = 0; j < MAX_DIGIT; ++j) {
                if (digitCounts[i][j] > 0) {
                    for (int k = 0; k < MAX_DIGIT; ++k) {
                        if (k != j) {
                            totalDiff += static_cast<long long>(digitCounts[i][j]) * digitDiffLookup[j][k];
                        }
                    }
                }
            }
        }
        return totalDiff;
    }
    vector<vector<int>> getDigitDiffLookup(int maxDigit) {
        vector<vector<int>> lookup(maxDigit, vector<int>(maxDigit, 0));
        for (int i = 0; i < maxDigit; ++i) {
            for (int j = 0; j < maxDigit; ++j) {
                lookup[i][j] = (i != j);
            }
        }
        return lookup;
    }
};

