        for(int i = 0; i < 2; i++) {
            for(int j = 0; j < 2; j++) {
                if(grid[i][j] == 'B') countB[i+j]++;
                else countW[i+j]++;
                if(grid[i][j+1] == 'B') countB[i+j+2]++;
                else countW[i+j+2]++;
            }
        }
        for(int i = 0; i < 4; i++) {
            if(countB[i] >= 3 || countW[i] >= 3) return true;
        }
        return false;
    }
};

