class Solution {
public:
    bool canWin(string s) {
        int n = s.size();
        vector<vector<bool>> dp(n, vector<bool>(n, false));
        for (int i = 0; i < n; i++) {
            dp[i][i] = false;
        }
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                bool hasOdd = false, hasEven = false;
                int vowelCount = 0;
                for (int k = i; k <= j; k++) {
                    if (s[k] == 'a' || s[k] == 'e' || s[k] == 'i' || s[k] == 'o' || s[k] == 'u') {
                        vowelCount++;
                    }
                }
                if (vowelCount % 2 == 1) {
                    hasOdd = true;
                } else if (vowelCount > 0) {
                    hasEven = true;
                }
                for (int k = i; k < j; k++) {
                    if (hasOdd && !dp[i][k]) {
                        dp[i][j] = true;
                        break;
                    }
                    if (hasEven && !dp[k + 1][j]) {
                        dp[i][j] = true;
                        break;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
};

