        sort(arr.begin(), arr.end());

        for(int i = 0; i < n; ++i)
        {
            if(i > 0 && arr[i] == arr[i-1]) continue;

            int lim = min(arr[i], arr.back() - arr[i]);

            for(int j = 0; j < lim; ++j)
