/*
My Intuition -
I think bitwise `AND` of 2 operands will always result in a number that is `<=` both operands. So if problem asks you to minimize result of multiple `AND` operation, then you would want to take all operands as much as possible.

"It's important to note that a walk may visit the same edge or vertex more than once." implies AND operation of all edges in a connected component.

So we use DSU.

Now question is how to get the ANDResult of a component. The way I initially thought was to store result of ANDResult at parent level and when performing Union, I get ANDResult from both u and v and put & it to new parent of (u,v) after Union.

The constraints say that s!=t, but if that was not the case then when s==t, min cost = 0.
*/
// modified DSU
const int speedup = [] { ios::sync_with_stdio(0); cin.tie(0); return 0; }();
class DSU {
    public:
    vector<int> parent,size,ANDResult;
    DSU(int n){
        parent.resize(n);
        iota(parent.begin(),parent.end(),0);
        size.resize(n,1);
        ANDResult.resize(n,-1);     // -1 has all bits set to 1
    }
    int Find(int v){
        if(parent[v]==v)
            return v;
        return parent[v] = Find(parent[v]);
    }
    void Union(int a, int b){
        a=Find(a);
        b=Find(b);
        if(a==b) return;
        if(size[a]<size[b])
            swap(a,b);
        parent[b]=a;
        size[a]+=size[b];
        ANDResult[a]&=ANDResult[b];
    }
};
class Solution {
public:
    vector<int> minimumCost(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
        int q=query.size();
        DSU dsu(n);
        vector<int> answer(q,-1);
        for(auto &edge:edges){
            int u=edge[0], v=edge[1], w=edge[2];
            dsu.Union(u,v);
            int p=dsu.Find(u);
            dsu.ANDResult[p]&=w;
        }
        for(int i=0;i<q;i++){
            int s=query[i][0], t=query[i][1];
            if(dsu.Find(s)!=dsu.Find(t)) continue;
            answer[i]=dsu.ANDResult[dsu.Find(s)];
        }
        return answer;
    }
};
