class Solution {
public:
    vector<int> occurrencesOfElement(vector<int>& nums, vector<int>& queries, int x) {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        cout.tie(nullptr);
        vector<int> occ;
        for(int i=0;i<nums.size();i++){
            if(nums[i] == x) occ.push_back(i);
        }
        vector<int> res(queries.size());
        for(int i=0;i<queries.size();i++){
            int left = 0, right = occ.size() - 1;
            while(left <= right){
                int mid = left + (right - left) / 2;
                if(occ[mid] == queries[i] - 1){
                    res[i] = occ[mid];
                    break;
                }else if(occ[mid] < queries[i] - 1){
                    left = mid + 1;
                }else{
                    right = mid - 1;
                }
            }
            if(left >= occ.size() || occ[left] != queries[i] - 1) res[i] = -1;
        }
