class Solution {
public:
    int sort(vector<int>& vec) {
        int min{INT_MAX}, max{0};
        for (const int i : vec) {
            min = std::min(min, i);
            max = std::max(max, i);
        }

        vector<bool> nums(max - min + 1);
        for (const int i : vec) {
            nums[i - min] = true;
        }

        int pos = 0;
        for (int i = 0; i < nums.size(); ++i) {
            if (!nums[i]) continue;

            vec[pos++] = i + min;
        }

        return pos - 1;
    }

    int maxTotalReward(vector<int>& rewardValues) {
        const auto end = rewardValues.begin() + sort(rewardValues);

        if (rewardValues.begin() == end) {
            return rewardValues.front();
        }

        vector<bool> seen(*end);

        auto it = rewardValues.begin();
        for (int i = 1; i < *end && !seen.back() && it != end; ++i) {
            if (!seen[i] && i < *it) continue;

            seen[*it] = true;
            it += i == *it;

            for (auto nit = it; nit != end; ++nit) {
                if (i + *nit >= *end) break;

                seen[i + *nit] = true;
            }
        }

        return *end + (seen.rend() - find(seen.rbegin(), seen.rend(), true)) - 1;
    }
};

