class Solution {
public:
    int maxTotalReward(std::vector<int>& rewardValues) {
        // Count the frequency of each reward value
        int maxReward = 0;
        for (int reward : rewardValues) {
            maxReward = std::max(maxReward, reward);
        }
        std::vector<int> frequency(maxReward + 1);
        for (int reward : rewardValues) {
            frequency[reward]++;
        }

        // Initialize dynamic programming table
        std::vector<int> dp(maxReward + 1);
        dp[0] = 0;

        // Iterate through the frequency table and compute the maximum total reward
        for (int i = 1; i <= maxReward; i++) {
            int maxRewardSoFar = 0;
            for (int j = 0; j < i; j++) {
                if (frequency[j] > 0) {
                    maxRewardSoFar = std::max(maxRewardSoFar, dp[j]);
                }
            }
            dp[i] = maxRewardSoFar + i * frequency[i];
        }

        // Return the maximum total reward
        return dp.back();
    }
};

