        for (const auto& q : queries) {
            int i = q[0] + sz;
            tree[i][0] = max(q[1], 0);
            while (i > 1) {
                i >>= 1;
                merge(tree[i], tree[i << 1], tree[(i << 1) + 1]);
            }
            res = (res + tree[1][0]) % MOD;
        }
        return res;
    }

