class Solution {
public:
    double findMinAverage(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        double ans = numeric_limits<double>::max();
        int l = 0, r = nums.size() - 1;
        for (; l < r; l++, r--) {
            double avg = (nums[l] + nums[r]) / 2.0;
            ans = min(ans, avg);
        }
        return ans;
    }
