class Solution {
public:
    bool isPossible(vector<int>& start, int d, int minDiff) {
        long long prev = (long long)start[0];
        for (int i = 1; i < start.size(); ++i) {
            long long candidate = max((long long)start[i], prev + minDiff);

            if (candidate > (long long)start[i] + d) {
                return false;
            }

            prev = candidate;
        }
        return true;
    }

    int maxPossibleScore(vector<int>& start, int d) {
        sort(start.begin(), start.end());
        int left = 0, right = 2 * 1e9, ans = 0; 
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (isPossible(start, d, mid)) {
                ans = mid;
                left = mid + 1; 
            } else {
                right = mid - 1; 
            }
        }
        return ans;
    }
};

