        vector<int> e;

        DSU(int n) : e(n, -1) {};

        int get(int v) { return e[v] < 0 ? v : e[v] = get(e[v]); }

        bool same_set(int v, int w) { return get(v) == get(w); } 

        int size(int v) { return -e[get(v)]; }

        bool unite(int v, int w) {
            v = get(v), w = get(w);
            if (v == w) return false;
            if (e[v] > e[w]) swap(v, w);
            e[v] += e[w];
            e[w] = v;
            return true;
        }
    };

