            vector<int> dir(n - 2, -1);
            u16 cant = 0;
            auto work = [&](int x, int d) {
                dir[x] = (dir[x] >= 0 && dir[x] != d) ? 0 : d;
            };
            for (int i = 0; i < n; ++i) {
                if (ans[i] != -1) {
                    int x = nums[ans[i]];
