    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long res = 0;
        int prefix = -1;
        unordered_map<int, int> seen = {{-1, 1}};
        for (int num : nums) {
            prefix &= num;
            if (prefix == k) {
                res += seen[k];
            } else {
                res += seen[prefix];
            }
            seen[prefix]++;
        }
        return res;
    }
}

