        int curr_bits = 0;
        int left = 0;

        for (int right = 0; right < n; right++) {
            curr_bits |= nums[right];
            int curr_count = get_bit_count(curr_bits);

            while (curr_count > k_bits) {
                curr_bits &= ~(nums[left]);
                left++;
