        int n = nums.size();
        long long res = 0;
        vector<int> count(32);
        count[0] = 1;
        int mask = 0;
        for (int num : nums) {
            mask &= num;
            if (mask == k) {
                res += count[0];
            }
            for (int i = 0; i < 32; i++) {
                if ((mask >> i) & 1) {
