class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long res = 0;
        for (int i = 0; i < 32; i++) {
            int cnt = 0;
            long long sum = 0;
            for (int j = 0; j < n; j++) {
                if ((nums[j] & (1 << i)) == (k & (1 << i)))
                    cnt++, sum += cnt;
                else
                    cnt = 0;
                res += cnt;
            }
        }
        return res;
    }
}

