                    swap(nums[pos], nums[i]);
                    continue;
                }
                res = (res + dfs(pos + 1, new_inversions)) % MOD;
                swap(nums[pos], nums[i]);
            }
            return res;
        };
        vector<int> nums(n);
        iota(nums.begin(), nums.end(), 0);
        return dfs(0, 0);
    }
};

