        for(int i = 1; i <= k; i++) v[i] += v[i-1];
        for(int i = 0; i <= k; i++){
            int total_one_change = (n/2) - freq[i];
            int additional_change = (i > 0) ? v[i - 1] : 0;
            ans = min(ans, total_one_change + additional_change);
        }
        return ans;
    }
};

