class Solution {
public:
    long long maxScore(vector<int>& a, vector<int>& b){
        int n = b.size();
        vector<ll> dp(n);
        dp[0] = (ll)a[0] * b[0];
        for(int i = 1; i < n; ++i){
            dp[i] = max(dp[i-1], (ll)a[0] * b[i]);
        }
        ll res = dp[n-1];
        for(int i = 1; i < n; ++i){
            ll cur = (ll)a[1] * b[i] + dp[i-1];
            res = max(res, cur);
            dp[i] = max(dp[i], cur);
        }
        for(int i = 2; i < n; ++i){
            ll cur = (ll)a[2] * b[i] + dp[i-1];
            res = max(res, cur);
        }
        for(int i = 3; i < n; ++i){
            ll cur = (ll)a[3] * b[i] + dp[i-1];
            res = max(res, cur);
        }
        return res;
    }
