class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& q) {
        // Initialize dp array with initial values
        vector<int> dp(n, INT_MAX);
        dp[0] = 0;

        vector<vector<int>> graph(n);
        for (int i = 0; i < n - 1; i++) {
            graph[i].push_back(i + 1);
        }

        vector<int> ans;
        for (auto query : q) {
            int u = query[0], v = query[1];
            graph[u].push_back(v);

            // Update dp array for each query
            for (int i = 0; i < n; i++) {
                for (int neighbor : graph[i]) {
                    dp[neighbor] = min(dp[neighbor], dp[i] + 1);
                }
            }

            ans.push_back(dp[n - 1]);
        }
        return ans;
    }
};

