class Solution {
public:
    bool canAliceWin(int n) {
        constexpr int k_N = 10, k_Total = (k_N+1)*k_N/2;
        int l = 0, h = k_N, numRemTurns = k_N;
        while (l <= h) {
            if (const int m = midpoint(l, h); (k_Total - ((m+1)*m/2)) <= n)
                numRemTurns = m, h = m-1;
            else
                l = m+1;
        }
        const int numTurns = k_N - numRemTurns;
        return (numTurns & 1) != 0;
    }
};

