class Solution {
public:
    bool findSafeWalk(vector<vector<int>>& grid, int health) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> dist(m, vector<int>(n, INT_MAX));
        dist[0][0] = grid[0][0];
        queue<pair<int, int>> q({{0, 0}});
        int dx[] = {0, 0, 1, -1}, dy[] = {1, -1, 0, 0};
        while (!q.empty()) {
            int x = q.front().first, y = q.front().second;
            q.pop();
            for (int i = 0; i < 4; ++i) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                    int newDist = dist[x][y] + grid[nx][ny];
                    if (newDist < dist[nx][ny]) {
                        dist[nx][ny] = newDist;
                        if (grid[nx][ny] == 0) q.push_front({nx, ny});
                        else q.push_back({nx, ny});
                    }
                }
            }
        }
        return dist.back().back() < health;
    }
};

class Solution {
public:
    bool canReach(vector<vector<int>>& grid, int health) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> dp(m, vector<int>(n, -1));
        function<bool(int, int, int)> dfs = [&](int i, int j, int h) {
            if (i < 0 || i >= m || j < 0 || j >= n || h <= 0) return false;
            if (dp[i][j] == h) return false;
            if (i == m - 1 && j == n - 1) return true;
            dp[i][j] = h;
            return dfs(i + 1, j, h - grid[i][j]) || dfs(i - 1, j, h - grid[i][j]) ||
                   dfs(i, j + 1, h - grid[i][j]) || dfs(i, j - 1, h - grid[i][j]);
        };
        return dfs(0, 0, health);
    }
};

