            int r = q.front().first, c = q.front().second;
            q.pop();
            int val = dp[r][c];
            if (r > 0 && dp[r-1][c] > val + grid[r-1][c]) {
                dp[r-1][c] = val + grid[r-1][c];
                q.emplace_back(r-1, c);
            }
            if (c > 0 && dp[r][c-1] > val + grid[r][c-1]) {
                dp[r][c-1] = val + grid[r][c-1];
                q.emplace_back(r, c-1);
            }
            if (r + 1 < m && dp[r+1][c] > val + grid[r+1][c]) {
                dp[r+1][c] = val + grid[r+1][c];
                q.emplace_back(r+1, c);
            }
            if (c + 1 < n && dp[r][c+1] > val + grid[r][c+1]) {
                dp[r][c+1] = val + grid[r][c+1];
                q.emplace_back(r, c+1);
            }
        }
        return dp.back().back() > 0;
    }
};

