        const int m = grid.size(), n = grid[0].size();
        vector<vector<int>> dp(m, vector<int>(health + 1, false));
        dp[0][health - grid[0][0]] = true;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == 0 && j == 0) continue;
                for (int k = 0; k <= health; ++k) {
                    if (dp[i][k]) {
                        if (i > 0 && k - grid[i][j] >= 0) dp[i - 1][k - grid[i][j]] = true;
                        if (j > 0 && k - grid[i][j] >= 0) dp[i][k - grid[i][j]] = true;
                        if (i < m - 1 && k - grid[i][j] >= 0) dp[i + 1][k - grid[i][j]] = true;
                        if (j < n - 1 && k - grid[i][j] >= 0) dp[i][k - grid[i][j]] = true;
                    }
                }
            }
        }
        return dp[m - 1][health];
    }
