class Solution {
public:
    vector<int> powerOfSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> results(n - k + 1, -1);
        deque<int> dq;
        for (int i = 0; i < n; i++) {
            while (!dq.empty() && nums[dq.back()] < nums[i]) {
                dq.pop_back();
            }
            dq.push_back(i);
            while (!dq.empty() && dq.front() <= i - k) {
                dq.pop_front();
            }
            if (i >= k - 1) {
                if (is_consecutive(nums, i - k + 1, i)) {
                    results[i - k + 1] = nums[dq.front()];
                }
            }
        }
        return results;
    }

    bool is_consecutive(vector<int>& nums, int start, int end) {
        for (int i = start; i < end; i++) {
            if (nums[i] + 1 != nums[i + 1]) {
                return false;
            }
        }
        return true;
    }
};

