class SegmentTree {
private:
    vector<int> tree;
    vector<int>& nums;
public:
    SegmentTree(vector<int>& nums) : nums(nums) {
        tree.resize(4 * nums.size());
        buildTree(0, 0, nums.size() - 1);
    }

