class Solution {
public:
    int countOfPairs(vector<int>& nums) {
        typedef long long LL;
        static const int maxv = (int)1e3 + 1, mod = (int)1e9 + 7;
        static int f[2][maxv], cur = 0, pre = 1;
        int n = nums.size();
        for(int i = 0; i <= nums[0]; ++i)
            f[cur][i] = 1;
        for(int i = 1; i < n; ++i) {
            swap(cur, pre);
            // j <- k: k <= j && k <= nums[i-1] - nums[i] + j
            int dt = min(nums[i - 1] - nums[i], 0);
            for(int j = 0, k = 0, s = 0; j <= nums[i]; ++j) {
                for( ; k <= j + dt; (s += f[pre][k++]) >= mod && (s -= mod));
                f[cur][j] = s;
            }
        }
        int ans = 0;
        for(int i = 0; i <= nums[n - 1]; ++i)
            (ans += f[cur][i]) >= mod && (ans -= mod);
        return ans;
    }
};

