class Solution {
 public:
  int maxDistinctElements(vector<int>& nums, int k) {
    unordered_map<int, int> cnt;
    for (int x : nums) cnt[x]++;
    int res = 0;
    for (int x : cnt) {
      int c = x.second;
      int a = x.first - k;
      int b = x.first + k;
      if (cnt.find(a) == cnt.end()) {
        res += min(c, (int)cnt.size() - 1);
        cnt[a] = c;
      } else if (cnt.find(b) == cnt.end()) {
        res += min(c, (int)cnt.size() - 1);
        cnt[b] = c;
      } else {
        res++;
      }
    }
    return res;
  }
};

