    std::vector<int> validSequence(std::string word1, std::string word2) {
        int n = word1.size(), m = word2.size();
        std::vector<int> ans(m);
        int j = 0;
        for (int i = 0; i < n && j < m; ++i) {
            if (word1[i] == word2[j]) {
                ans[j++] = i;
            } else if (j && word1[i] == word2[j-1]) {
                ans[--j] = i;
            }
        }
        return j == m ? ans : std::vector<int>{};
    }
};

class Solution {
public:
    std::vector<int> findLexicographicallySmallestSequence(std::string word1, std::string word2) {
        int n = word1.size(), m = word2.size();
        std::vector<int> last(m, -1);
        for (int i = n - 1, j = m - 1; i >= 0 && j >= 0; --i) {
            if (word1[i] == word2[j]) {
                last[j--] = i;
            }
        }

        std::vector<int> res(m);
        int skip = 0;
        for (int i = 0; i < n && skip < m; ++i) {
            if (word1[i] == word2[skip]) {
                res[skip++] = i;
            } else if (skip > 0 && i < last[skip]) {
                res[skip++] = i;
            }
        }

        return skip == m ? res : std::vector<int>{};
    }
};

class Solution {
public:
    std::vector<int> validSequence(std::string word1, std::string word2) {
        int n = word1.size(), m = word2.size();
        std::vector<int> ans;
        int diffCount = 0;
        int lastMismatch = -1;
        for (int i = 0, j = 0; i < n && j < m; ++i) {
            if (word1[i] != word2[j]) {
                if (diffCount++ > 0) break;
                lastMismatch = i;
            } else {
                ans.push_back(i);
                ++j;
            }
        }
        if (diffCount == 0 && j == m) return ans;
        if (diffCount == 1 && j == m - 1) {
            ans.push_back(lastMismatch);
            return ans;
        }
        return {};
    }
};

