    string convertDateToBinary(string date) {
        int year, month, day;
        sscanf(date.c_str(), "%d-%d-%d", &year, &month, &day);

        string yearBin = bitset<32>(year).to_string();
        yearBin.erase(0, yearBin.find('1'));

        string monthBin = bitset<8>(month).to_string();
        monthBin.erase(0, monthBin.find('1'));

        string dayBin = bitset<8>(day).to_string();
        dayBin.erase(0, dayBin.find('1'));

        return yearBin + "-" + monthBin + "-" + dayBin;
    }
};

