class Solution {
public:
    int getLargestOutlier(vector<int>& nums) {
        int total = 0, minm = INT_MAX, maxm = INT_MIN, res = INT_MIN;
        for(int num : nums) {
            total += num;
            if(num > maxm) maxm = num;
            if(num < minm) minm = num;
        }
        // cout<<"minm: "<<minm<<" and maxm :"<<maxm<<endl;
        vector<int>occur(maxm - minm + 1, 0);
        for(int num : nums) occur[num - minm]++;

        for(int i = maxm;i >= minm;i--) {// outlier
            if(occur[i - minm] == 0) continue ;
            occur[i - minm]--;
            // cout<<"total: "<<total<<" outlier: "<<i<<" and sum: "<<((total - i)/2)<<endl;
            int rem = ((total - i)/2);
            if((total - i) %2 == 0 && 
                rem >= minm &&
                rem <= maxm &&
                occur[rem - minm] > 0) return i;
            occur[i - minm]++;
        }
        return res;
    }
};


