    vector<int> minBitwiseArray(vector<int>& nums) {
        vector<int> ans(nums.size());

        for (int i = 0; i < nums.size(); i++) {
            int num = nums[i];

            if (num == 2) {
                ans[i] = -1;
                continue;
            }

            int count = 0;
            int numCopy = num - 1;

            // Count consecutive 1s from the right
            while ((numCopy & 1) == 1) {
                count++;
                numCopy >>= 1;
            }

            // Calculate ans[i] based on the count and num[i]
            ans[i] = num - (1 << count);
        }

        return ans;
    }
};

