        int ans = 0;
        for (int i = 0; i < n / 2; ++i) {
            for (int j = 0; j < m / 2; ++j) {
                int ones = grid[i][j] + grid[n - i - 1][j] + grid[i][m - j - 1] + grid[n - i - 1][m - j - 1];
                ans += min(ones, 4 - ones);
            }
        }
        if (n % 2) {
            for (int j = 0; j < m / 2; ++j) {
                if (grid[n / 2][j] != grid[n / 2][m - j - 1]) {
                    ans++;
                }
            }
        }
        if (m % 2) {
            for (int i = 0; i < n / 2; ++i) {
                if (grid[i][m / 2] != grid[n - i - 1][m / 2]) {
                    ans++;
                }
            }
        }
        if (n % 2 == 1 && m % 2 == 1 && grid[n / 2][m / 2]) {
            ans++;
        }
