void linear_sieve_of_eratosthenes() {
    for (int i = 2; i <= MAX_N; ++i) {
        if (spf[i] == -1) {
            spf[i] = i;
        }
        for (int j = 2; j * i <= MAX_N; ++j) {
            if (spf[i] == -1 || spf[j] == j) {
                if (spf[i] == -1) spf[i * j] = j;
                else spf[i * j] = spf[i];
            } else {
                break;
            }
        }
    }
