            if (nums[i] <= nums[i + 1]) {
                continue;
            }
            int div = nums[i];
            while (div > nums[i + 1]) {
                div /= spf[div];
                if (div == 1) {
                    return -1;
                }
            }
            nums[i] = div;
            ++result;
        }
        return result;
