const int MAX_N = 1e6;
const auto& SPF = linear_sieve_of_eratosthenes(MAX_N);
class Solution {
public:
    int minOperations(vector<int>& nums) {
        int n = size(nums);
        int dp[n];
        for (int i = 0; i < n; ++i) {
            dp[i] = 0;
        }
        for (int i = n - 2; i >= 0; --i) {
            if (nums[i] <= nums[i + 1]) {
                dp[i] = dp[i + 1];
                continue;
            }
            int curr = nums[i];
            int ops = 0;
            while (curr > nums[i + 1]) {
                curr /= SPF[curr];
                ++ops;
            }
            if (curr < nums[i + 1]) {
                dp[i] = ops + dp[i + 1];
            } else {
                dp[i] = -1;
                break;
            }
        }
        return dp[0] == -1 ? -1 : dp[0];
    }
};
