class Solution {
    int maxFrequencyToNum(vector<int>& nums, int k, int numOperations) {
        int n = nums.size(), ans = 0, curr_num_freq = 0;
        for(int i = 0, l = 0, r = 0; i < n; i++) {
            if (i > 0 && nums[i] != nums[i - 1]) curr_num_freq = 1;
            else curr_num_freq++;

            while(r < n && nums[r] - nums[i] <= k) {
                r++;
            }
            while (l < i && nums[i] - nums[l] > k) {
                l++;
            }
            // l is within bounds, r is out of bounds
            int left_ops = i - l + 1 - curr_num_freq, right_ops = r - i - 1;
            ans = max(ans, min(numOperations, left_ops + right_ops) + curr_num_freq);
