vector<int> findXSum(vector<int>& nums, int k, int x) {
    int n = nums.size();
    vector<int> result(n - k + 1);
    vector<pair<int, int>> freq;
    map<int, int> count;

    for (int i = 0; i < k; ++i) {
        ++count[nums[i]];
    }

    for (auto& p : count) {
        freq.push_back(p);
    }

    sort(freq.begin(), freq.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second > b.second || (a.second == b.second && a.first > b.first);
    });

    int sum = 0;
    for (int i = 0; i < x && i < freq.size(); ++i) {
        sum += freq[i].first * freq[i].second;
    }

    result[0] = sum;

    for (int i = k; i < n; ++i) {
        int out = nums[i - k];
        int in = nums[i];

        --count[out];
        if (count[out] == 0) {
            erase(freq, out, count);
        } else {
            update(freq, out, count);
        }

        ++count[in];
        insert(freq, in, count);

        sum = 0;
        for (int j = 0; j < x && j < freq.size(); ++j) {
            sum += freq[j].first * freq[j].second;
        }

        result[i - k + 1] = sum;
    }

    return result;
}

void erase(vector<pair<int, int>>& freq, int val, map<int, int>& count) {
    for (auto it = freq.begin(); it != freq.end(); ++it) {
        if (it->first == val) {
            freq.erase(it);
            break;
        }
    }
    sort(freq.begin(), freq.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second > b.second || (a.second == b.second && a.first > b.first);
    });
}

void update(vector<pair<int, int>>& freq, int val, map<int, int>& count) {
    for (auto& p : freq) {
        if (p.first == val) {
            p.second = count[val];
            break;
        }
    }
    sort(freq.begin(), freq.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second > b.second || (a.second == b.second && a.first > b.first);
    });
}

void insert(vector<pair<int, int>>& freq, int val, map<int, int>& count) {
    freq.push_back({val, count[val]});
    sort(freq.begin(), freq.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second > b.second || (a.second == b.second && a.first > b.first);
    });
}

