        for (int i = 0; i < seq.size(); ++i) {
            int u = seq[i];
            for (int v : adj[u]) if (v != par[u]) {
                seq.push_back(v);
                par[v] = u;
            }
        }

        dep[0] = 0;
        for (int i = 1; i < seq.size(); ++i) {
            int u = seq[i];
            dep[u] = dep[par[u]] + 1;
        }

        auto dfs = [&](int u) {
            int t0 = dep[u] + (u & 1), t1 = t0;
            for (int v : adj[u]) if (v != par[u]) {
                int t = dfs(v);
                t0 = max(t0, t + 2 - (v & 1));
                t1 = max(t1, t + 1 + !(u & 1));
            }
            res[u] = t0;
            return t1;
        };

        dfs(0);
        return res;
    }
