        if (t[v].next[c] == -1) {
            t[v].next[c] = t.size();
            t.emplace_back(v, ch, depth);
        }
        v = t[v].next[c];
    }
    t[v].leaf = true;
    t[v].cost = min(t[v].cost, cost);
}

int go(int v, char ch);

int get_link(int v) {
    if (t[v].link == -1) {
        if (v == 0 || t[v].p == 0)
            t[v].link = 0;
        else
            t[v].link = go(get_link(t[v].p), t[v].pch);
    }
    return t[v].link;
}

int go(int v, char ch) {
    int c = ch - 'a';
    if (t[v].go[c] == -1) {
        if (t[v].next[c] != -1)
            t[v].go[c] = t[v].next[c];
        else
            t[v].go[c] = v == 0 ? 0 : go(get_link(v), ch);
    }
    return t[v].go[c];
}

int up(int v) {
    if (t[v].up == -1) {
        if (v == 0 || t[v].p == 0) {
            t[v].up = 0;
        } else {
            int u = get_link(v);
            if (t[u].leaf || u == 0) {
                t[v].up = u;
            } else {
                t[v].up = up(u);
            }
        }
    }
    return t[v].up;
}

template<typename T>
struct DequeMin {
    deque<T> dq;

    bool isEmpty() {
        return dq.empty();
    }

    void add(T x) {
        while (!dq.empty() && dq.back() > x) {
            dq.pop_back();
        }
        dq.emplace_back(x);
    }

    void remove(T x) {
        if (dq.empty() || dq.front() != x) {
            return;
        }
        dq.pop_front();
    }

    T getMin() {
        return dq.front();
    }
};

