class Solution {
public:
    // main idea is to calculate the count of good subseq ending at value(val) at index i from [0...i-1]
    // whyvalue not index -> since to calculate dp[3] (val =3) = 1+dp[2]  and also dp[4]
    // we dont need index (since before morethan one index might havve value 2)
    // we will use value

    int mod = 1e9+7;
    int sumOfGoodSubsequences(vector<int>& nums) {
        int maxValue = 100001;
        vector<long> dp(maxValue,0); // to count the number of good sebseq ending at value = val
        vector<long> sum(maxValue,0); // to get the sum of good sebseq ending at value = val

        for(auto &it: nums){
            dp[it] = (dp[it] + 1) % mod; // adding a single count;
            sum[it] = (sum[it] + it) % mod; // adding one time;

            // checking for oneless value
            if(it-1 >= 0 && dp[it-1] > 0){
                dp[it] = (dp[it] + dp[it-1])%mod;
                sum[it] = (sum[it] + (sum[it-1] + (it * dp[it-1]) % mod) % mod )%mod;
            }
            // checking for oneGreater value
            if(it+1 < maxValue && dp[it+1] > 0){
                dp[it] = (dp[it] + dp[it+1])%mod;
                sum[it] = (sum[it] + (sum[it+1] + (it * dp[it+1]) % mod) % mod)%mod;
            }
        }

        long long ans = 0;
        for(int i=0;i<maxValue;i++){
            ans = (ans+sum[i])%mod;
        }
        return (int)ans;

    }
};

