class Solution {
public:
    string answerString(string str, int numFriends) {
        if(numFriends==1) return str; //edge case

        int n = str.length();  
        int i = 0, j = 1, k = 0;

        while(j+k < n){
            if(str[i+k]==str[j+k]){
                k++;
            }else if(str[i+k]>str[j+k]){
                j = j + k + 1;
                k = 0;
            }else{
                i = max(i+k+1, j);
                j = i + 1;
                k = 0;
            }
        }

        if (i+1 >= numFriends)  return str.substr(i);
        return str.substr(i, (n-i)-(numFriends-i-1));
    }
};

