        vector<vector<int>> graph1 = getGraph(e1);
        vector<vector<int>> graph2 = getGraph(e2);
        vector<int> res(n, 0);
        vector<int> diameter1 = getDiameter(graph1);
        vector<int> diameter2 = getDiameter(graph2);
        for (int i = 0; i < n; i++) {
            int maxNodes = 0;
            for (int j = 0; j < m; j++) {
                int nodes = bfs(graph1, i, k) + bfs(graph2, j, k);
                maxNodes = max(maxNodes, nodes);
            }
            res[i] = maxNodes;
        }
        return res;
    }
    vector<vector<int>> getGraph(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> graph(n);
        for (auto& edge : edges) {
            graph[edge[0]].push_back(edge[1]);
            graph[edge[1]].push_back(edge[0]);
        }
        return graph;
    }
    vector<int> getDiameter(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> dist(n, -1);
        queue<int> q;
        q.push(0);
        dist[0] = 0;
        int maxDist = 0, maxNode = 0;
        while (!q.empty()) {
            int node = q.front(); q.pop();
            for (int neighbor : graph[node]) {
                if (dist[neighbor] == -1) {
                    dist[neighbor] = dist[node] + 1;
                    q.push(neighbor);
                    if (dist[neighbor] > maxDist) {
                        maxDist = dist[neighbor];
                        maxNode = neighbor;
                    }
                }
            }
        }
        return dist;
    }
    int bfs(vector<vector<int>>& graph, int start, int k) {
        int n = graph.size();
        vector<int> dist(n, -1);
        queue<int> q;
        q.push(start);
        dist[start] = 0;
        int count = 0;
        while (!q.empty()) {
            int node = q.front(); q.pop();
            count++;
            if (dist[node] == k) continue;
            for (int neighbor : graph[node]) {
                if (dist[neighbor] == -1) {
                    dist[neighbor] = dist[node] + 1;
                    q.push(neighbor);
                }
            }
        }
        return count;
    }
