using LL = long long;
constexpr int MOD = 1e9+7;

class Solution {
public:
    int countKReducibleNumbers(string s, int k) {
        int n = s.size();
        LL ans = 0;
        vector<int> bits(n);
        for (int i = 0; i < n; ++i) {
            bits[i] = s[i] - '0';
        }
        function<int(int)> popcount = [&](int x) {
            int cnt = 0;
            while (x) {
                cnt += x & 1;
                x >>= 1;
            }
            return cnt;
        };
        for (int v = 1; v < (1 << n); ++v) {
            int val = v;
            int steps = 0;
            while (val != 1 && steps <= k) {
                val = popcount(val);
                steps++;
            }
            if (val == 1 && steps <= k) {
                int cur = 0;
                bool ok = true;
                for (int i = 0; i < n; ++i) {
                    cur += bits[i];
                    if (cur > v) {
                        ok = false;
                        break;
                    }
                    if (bits[i]) {
                        cur -= 1;
                    }
                }
                if (ok) {
                    ans++;
                }
            }
        }
        return ans % MOD;
    }
};

