class Solution {
    public:
        long long minCost(vector<int>& arr, vector<int>& brr, long long k) {
            int n = arr.size();
            sort(arr.begin(), arr.end());
            sort(brr.begin(), brr.end());
            long long ans = k + accumulate(arr.begin(), arr.end(), 0LL) - accumulate(brr.begin(), brr.end(), 0LL);
            ans = abs(ans);
            return ans;
        }
};

