                    int val = coins[i][j];
                    int noShield = val;          // 不用技能
                    int useShield = max(0,val); // 用技能，负数变0，正数不变

                    // 从上或左来
                    if (i > 0) {
                        if (dp[i - 1][j][k] != INT_MIN)
                            dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] + noShield);
