        for (int i = prev + 1; i < n; ++i) if (st[B+i] != -1) {
            int sz = i - prev;
            fwd[prev] = i; prev = i;
            ++cnts[sz]; sums[sz] += sz; ++C;
        }
        fwd[prev] = first;
        int sz = n - (prev - first);
        ++cnts[sz]; sums[sz] += sz; ++C;
    } else {
        ++cnts[1]; ++cnts[n-1];
        ++sums[1]; sums[n-1] += n-1;
        C = 2;
    }
    fillbt(cnts);
    fillbt(sums);
