class Solution {
public:
    int maxFreeTime(int eventTime, vector<int>& startTime, vector<int>& endTime) {
        int n = startTime.size();
        vector<pair<int, int>> meetings;
        for (int i = 0; i < n; i++) {
            meetings.push_back({startTime[i], endTime[i]});
        }
        sort(meetings.begin(), meetings.end());

        int maxFreeTime = 0;
        for (int i = 0; i < n; i++) {
            int freeTime = 0;
            if (i > 0) {
                freeTime = max(freeTime, meetings[i].first - meetings[i-1].second);
            }
            if (i < n - 1) {
                freeTime = max(freeTime, meetings[i+1].first - meetings[i].second);
            }
            if (i > 0 && i < n - 1) {
                freeTime = max(freeTime, meetings[i+1].first - meetings[i-1].second - (meetings[i].second - meetings[i].first));
            }
            maxFreeTime = max(maxFreeTime, freeTime);
        }
        maxFreeTime = max(maxFreeTime, meetings[0].first);
        maxFreeTime = max(maxFreeTime, eventTime - meetings[n-1].second);

        return maxFreeTime;
    }
};

