#include <string>
#include <vector>
#include <map> // Can be used, but vector is slightly more efficient for small fixed range keys

using namespace std;

class Solution {
public:
    /**
     * @brief Counts the number of substrings divisible by their non-zero last digit.
     * @param s The input string consisting of digits.
     * @return The total count of such substrings.
     *
     * The approach iterates through the string using index j as the end position of potential substrings.
     * For each j, if the digit s[j] is non-zero, it determines the divisor k = value(s[j]).
     * Then, it checks all substrings s[i..j] (for 0 <= i <= j) for divisibility by k.
     * To do this efficiently in O(N) time, we use prefix properties and frequency maps/arrays.
     *
     * For k = 1, 2, 5: The divisibility condition is always met. Add j+1 to the count.
     * For k = 3, 6, 9: Divisibility depends on the sum of digits modulo 3 or 9. We use prefix sums S[j] = sum(s[0..j]) and frequency maps.
     *      Condition Sum[i..j] % m == 0 is equivalent to S[j] % m == S[i-1] % m (where m=3 or 9).
     *      The count of valid i's is the frequency of S[j] % m among previous prefix sums S[-1]..S[j-1].
     * For k = 4, 8: Divisibility depends on the last few digits. Specific rules are applied based on s[j], s[j-1], s[j-2].
     * For k = 7: Divisibility rule is complex. We use a transformation: N(i, j) % 7 == 0 is equivalent to R[j] % 7 == R[i-1] % 7,
     *      where R[x] = P[x] * (10^{-1})^{x+1} mod 7. P[x] is the value of prefix s[0..x]. 10^{-1} mod 7 is 5.
     *      We maintain frequencies of R values modulo 7.
     *
     * All checks and updates are done in O(1) time per index j, leading to O(N) total time complexity.
     * Space complexity is O(1) because the frequency arrays have constant sizes (3, 9, 7).
     */
    long long countSubstrings(string s) {
        long long ans = 0; // Use long long for the answer as it can exceed 32-bit integer limit.
        int n = s.length();

        // Frequency arrays to store counts of prefix properties modulo 3, 9, and 7 (for R value).
        // The index represents the remainder/value, and the value at that index is the count of prefixes having that property.
        vector<long long> freq3(3, 0); 
        vector<long long> freq9(9, 0); 
        vector<long long> freq7(7, 0); 

        // Initialize counts for the empty prefix (considered index -1).
        // Empty prefix sum is 0. Its corresponding R value R[-1] is also 0.
        freq3[0] = 1;
        freq9[0] = 1;
        freq7[0] = 1; 

        int S3 = 0; // Current prefix sum modulo 3, S[j] = Sum(s[0..j]) mod 3
        int S9 = 0; // Current prefix sum modulo 9, S[j] = Sum(s[0..j]) mod 9
        int P7 = 0; // Current prefix value P[j] = Value(s[0..j]) mod 7

        // current_pow5 stores 5^(idx+1) mod 7. It's needed for calculating R[idx].
        // Starts at 5^0=1 (for state before index 0). Updated inside loop before use for index j.
        long long current_pow5 = 1; 

        // Iterate through the string using index j as the end position of substrings.
        for (int j = 0; j < n; ++j) {
            int v_j = s[j] - '0'; // Get the numeric value of the current digit s[j].

            // Update prefix properties based on the current digit v_j.
            S3 = (S3 + v_j) % 3;
            S9 = (S9 + v_j) % 9;
            P7 = (P7 * 10 + v_j) % 7; // Update prefix value P[j] modulo 7

            // Update the power of 5: needed for R[j]. We need 5^(j+1) mod 7.
            // current_pow5 was 5^j before this update, now becomes 5^(j+1).
            current_pow5 = (current_pow5 * 5) % 7; 

            // Calculate R[j] = P[j] * 5^(j+1) mod 7. Use 1LL for intermediate multiplication to avoid overflow.
            int R7 = (1LL * P7 * current_pow5) % 7;

            // Only consider substrings ending with a non-zero digit.
            if (v_j != 0) {
                int k = v_j; // The divisor k is the value of the last digit.

                // Apply divisibility rules based on k.
                if (k == 1 || k == 2 || k == 5) {
                    // For k=1, any integer is divisible by 1.
                    // For k=2, N(i, j) = N(i, j-1)*10 + 2 is always even.
                    // For k=5, N(i, j) = N(i, j-1)*10 + 5 is always divisible by 5.
                    // In these cases, all j+1 substrings ending at j (i=0..j) are valid.
                    ans += (long long)(j + 1); 
                } else if (k == 3 || k == 6) {
                    // For k=3, need N(i,j) % 3 == 0 <=> Sum[i..j] % 3 == 0.
                    // For k=6, need N(i,j) % 6 == 0. Since v_j=6, N(i,j) is always even.
                    // So we only need N(i,j) % 3 == 0 <=> Sum[i..j] % 3 == 0.
                    // Condition Sum[i..j] % 3 == 0 is equivalent to S[j] % 3 == S[i-1] % 3.
                    // The number of valid starting indices i is the count of previous prefixes p=i-1
                    // (including empty prefix p=-1) such that S[p] % 3 == S[j] % 3. This count is freq3[S3].
                    ans += freq3[S3];
                } else if (k == 4) {
                    // N(j, j) = 4 is divisible by 4.
                    ans += 1; 
                    // For i < j, N(i, j) % 4 depends on last two digits. N(i, j) % 4 = (v_{j-1}*10 + 4) % 4 = (v_{j-1}*2) % 4.
                    // This is 0 iff v_{j-1} is even (0, 2, 4, 6, 8).
                    if (j >= 1) {
                        int v_j_1 = s[j-1] - '0';
                        if (v_j_1 % 2 == 0) {
                             // Substrings s[0..j] to s[j-1..j] are valid. There are j such substrings.
                             ans += (long long)j; 
                        }
                    }
                } else if (k == 7) {
                    // Need N(i, j) % 7 == 0. Using the transformation, this is equivalent to R[j] % 7 == R[i-1] % 7.
                    // The number of valid starting indices i is the count of previous prefixes p=i-1
                    // such that R[p] % 7 == R[j] % 7. This count is freq7[R7].
                    ans += freq7[R7];
                } else if (k == 8) {
                    // N(j, j) = 8 is divisible by 8.
                    ans += 1; 
                    // Check N(j-1, j) % 8 = (v_{j-1}*10 + 8) % 8 = (v_{j-1}*2) % 8. This is 0 iff v_{j-1} is 0, 4, 8.
                    if (j >= 1) {
                        int v_j_1 = s[j-1] - '0';
                        if ((v_j_1 * 2) % 8 == 0) { 
                            ans += 1; // Substring s[j-1..j]
                        }
                    }
                    // Check N(i, j) % 8 for i <= j-2. This depends on N(j-2, j) % 8.
                    // N(j-2, j) % 8 = (v_{j-2}*100 + v_{j-1}*10 + 8) % 8 = (v_{j-2}*4 + v_{j-1}*2) % 8.
                     if (j >= 2) {
                        int v_j_1 = s[j-1] - '0';
                        int v_j_2 = s[j-2] - '0';
                        if ((v_j_2 * 4 + v_j_1 * 2) % 8 == 0) {
                             // If N(j-2, j) is divisible by 8, then all N(i, j) for i <= j-2 are also divisible by 8.
                             // Substrings s[0..j] to s[j-2..j] are valid. There are j-1 such substrings (i=0 to j-2).
                             ans += (long long)(j - 1); 
                        }
                    }
                } else if (k == 9) {
                    // Need N(i,j) % 9 == 0 <=> Sum[i..j] % 9 == 0.
                    // Equivalent to S[j] % 9 == S[i-1] % 9. The count is freq9[S9].
                    ans += freq9[S9];
                }
            }

            // After processing index j and potentially adding to ans, update frequency counts
            // based on the properties of the prefix ending at j. These updated counts will be used for future indices > j.
            freq3[S3]++;
            freq9[S9]++;
            freq7[R7]++; // R7 calculated corresponds to index j.
        }

        return ans;
    }
};

