            S9 = (S9 + v_j) % 9;
            P7 = (P7 * 10 + v_j) % 7; // Update prefix value P[j] modulo 7

            // Update the power of 5: needed for R[j]. We need 5^(j+1) mod 7.
            // current_pow5 was 5^j before this update, now becomes 5^(j+1).
            current_pow5 = (current_pow5 * 5) % 7; 

            // Calculate R[j] = P[j] * 5^(j+1) mod 7. Use 1LL for intermediate multiplication to avoid overflow.
            int R7 = (1LL * P7 * current_pow5) % 7;

