            if (v_j != 0) {
                int k = v_j; // The divisor k is the value of the last digit.

                // Apply divisibility rules based on k.
                if (k == 1 || k == 2 || k == 5) {
                    // For k=1, any integer is divisible by 1.
                    // For k=2, N(i, j) = N(i, j-1)*10 + 2 is always even.
                    // For k=5, N(i, j) = N(i, j-1)*10 + 5 is always divisible by 5.
