                    // Condition Sum[i..j] % 3 == 0 is equivalent to S[j] % 3 == S[i-1] % 3.
                    // The number of valid starting indices i is the count of previous prefixes p=i-1
                    // (including empty prefix p=-1) such that S[p] % 3 == S[j] % 3. This count is freq3[S3].
                    ans += freq3[S3];
                } else if (k == 4) {
                    // N(j, j) = 4 is divisible by 4.
                    ans += 1; 
                    // For i < j, N(i, j) % 4 depends on last two digits. N(i, j) % 4 = (v_{j-1}*10 + 4) % 4 = (v_{j-1}*2) % 4.
                    // This is 0 iff v_{j-1} is even (0, 2, 4, 6, 8).
