                        }
                    }
                    // Check N(i, j) % 8 for i <= j-2. This depends on N(j-2, j) % 8.
                    // N(j-2, j) % 8 = (v_{j-2}*100 + v_{j-1}*10 + 8) % 8 = (v_{j-2}*4 + v_{j-1}*2) % 8.
