                     if (j >= 2) {
                        int v_j_1 = s[j-1] - '0';
                        int v_j_2 = s[j-2] - '0';
                        if ((v_j_2 * 4 + v_j_1 * 2) % 8 == 0) {
                             // If N(j-2, j) is divisible by 8, then all N(i, j) for i <= j-2 are also divisible by 8.
                             // Substrings s[0..j] to s[j-2..j] are valid. There are j-1 such substrings (i=0 to j-2).
                             ans += (long long)(j - 1); 
                        }
                    }
                } else if (k == 9) {
                    // Need N(i,j) % 9 == 0 <=> Sum[i..j] % 9 == 0.
                    // Equivalent to S[j] % 9 == S[i-1] % 9. The count is freq9[S9].
                    ans += freq9[S9];
                }
            }

            // After processing index j and potentially adding to ans, update frequency counts
            // based on the properties of the prefix ending at j. These updated counts will be used for future indices > j.
            freq3[S3]++;
            freq9[S9]++;
            freq7[R7]++; // R7 calculated corresponds to index j.
        }

        return ans;
    }
};
